-- source: AI经营分析报告/正式系统/DDL_draft.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_business_target (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  target_type   ENUM('monthly','quarterly') NOT NULL COMMENT '月度/季度',
  period_key    VARCHAR(10) NOT NULL COMMENT '2026-07 或 2026-Q3',
  platform      VARCHAR(20) NOT NULL DEFAULT 'walmart',
  owner         VARCHAR(64) NOT NULL COMMENT '负责人姓名（与周报owner口径一致）',
  metric        ENUM('sales','profit') NOT NULL COMMENT '销售额/毛利润',
  target_value  DECIMAL(14,2) NOT NULL,
  created_by    VARCHAR(64) NOT NULL COMMENT '首次设定人',
  updated_by    VARCHAR(64) NOT NULL COMMENT '最近调整人',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_target (target_type, period_key, platform, owner, metric),
  KEY idx_period (period_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='业绩目标（人工数据，密码门禁写入，AI只读）';

-- source: AI经营分析报告/正式系统/DDL_draft.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_business_target_change_log (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  target_id     BIGINT UNSIGNED NOT NULL,
  target_type   ENUM('monthly','quarterly') NOT NULL,
  period_key    VARCHAR(10) NOT NULL,
  platform      VARCHAR(20) NOT NULL,
  owner         VARCHAR(64) NOT NULL,
  metric        ENUM('sales','profit') NOT NULL,
  old_value     DECIMAL(14,2) NULL COMMENT '首次设定为NULL',
  new_value     DECIMAL(14,2) NOT NULL,
  action        ENUM('create','update') NOT NULL,
  change_source ENUM('manual','import') NOT NULL COMMENT '手动修改/表格批量导入',
  changed_by    VARCHAR(64) NOT NULL,
  changed_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_target (target_id),
  KEY idx_period_owner (period_key, owner)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='目标变更流水（全员可查，不覆盖历史）';

-- source: AI经营分析报告/正式系统/DDL_draft.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS ai_business_report (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  report_type       VARCHAR(32) NOT NULL COMMENT 'weekly/monthly/adhoc...',
  period_key        VARCHAR(16) NOT NULL COMMENT '2026-W28 / 2026-07 / 自定义',
  win_start         DATE NOT NULL,
  win_end           DATE NOT NULL,
  filter_json       JSON NULL COMMENT '生成时的筛选条件（手动生成必填）',
  out_dir           VARCHAR(255) NOT NULL,
  completeness_json JSON NULL,
  status            VARCHAR(16) NOT NULL COMMENT 'success/failed/running',
  trigger_source    VARCHAR(16) NOT NULL COMMENT 'cron/manual',
  notify_json       JSON NULL COMMENT '群通知+私聊发送结果',
  generated_at      DATETIME NOT NULL,
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_type_period (report_type, period_key),
  KEY idx_generated (generated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报表登记（AI层，报表中心数据源）';

