-- source: AI经营分析报告/正式系统/交付件/event_ops_inaction_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_ops_inaction_alert (
  id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  platform      VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id      VARCHAR(64)  NOT NULL,
  item_id       VARCHAR(64)  NOT NULL,
  mskus         VARCHAR(200) NOT NULL DEFAULT '',
  owner         VARCHAR(64)  NOT NULL DEFAULT '',
  pool_reason   VARCHAR(100) NOT NULL COMMENT '入池原因：7天不出单 / D级 / 7天不出单+D级',
  rule_hit      VARCHAR(40)  NOT NULL COMMENT '触发规则：R1连续5天无动作 / R2近8天≥5天无动作',
  window_detail JSON         NULL COMMENT '判定明细：[{d:日志日,act:0/1}]，act=1为有实质动作',
  alert_date    DATE         NOT NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  resolved_at   DATETIME     NULL,
  resolved_note VARCHAR(200) NULL,
  UNIQUE KEY uk_alert (platform, store_id, item_id, alert_date),
  KEY idx_open (platform, resolved_at),
  KEY idx_item (platform, store_id, item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='EVENT层：重点产品（7天不出单/D级）无运营动作通报';

