CREATE TABLE IF NOT EXISTS fact_onsite_ads_invoice_head (
  id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  platform VARCHAR(32) NOT NULL DEFAULT 'walmart',
  store_id VARCHAR(64) NOT NULL COMMENT '店铺ID',
  store_name VARCHAR(255) NULL,
  account_number VARCHAR(32) NOT NULL DEFAULT '' COMMENT 'Connect广告账号(PDF头部)',
  invoice_number VARCHAR(40) NOT NULL COMMENT '发票号',
  invoice_date DATE NULL COMMENT '开票日',
  charge_date DATE NULL COMMENT '实际扣款日',
  period_start DATE NOT NULL COMMENT '账期起',
  period_end DATE NOT NULL COMMENT '账期止(含)',
  subtotal DECIMAL(18,2) NOT NULL DEFAULT 0 COMMENT '明细小计',
  total_ad_spend DECIMAL(18,2) NOT NULL DEFAULT 0 COMMENT '广告花费总额(对账日绩效用这个,勿用实扣额)',
  total_credits_applied DECIMAL(18,2) NOT NULL DEFAULT 0 COMMENT '发票内credit抵扣(负数;店铺账单看不到这类credit)',
  total_charged DECIMAL(18,2) NOT NULL DEFAULT 0 COMMENT '实扣额=AdSpend+Credit',
  payment_method VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'Seller Center(余额,进statement)/Credit Card(不进statement)',
  line_count INT NOT NULL DEFAULT 0,
  source_task_id VARCHAR(40) NULL,
  remark VARCHAR(500) NULL COMMENT '人工备注(系统不覆盖)',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_foai_head (store_id, invoice_number),
  KEY idx_foai_head_period (store_id, period_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: Connect站内广告发票头(费用/credit权威源;statement广告类目仅参考)';

