CREATE TABLE IF NOT EXISTS event_clearance_approval (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  platform        VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id        VARCHAR(64)  NOT NULL,
  store_name      VARCHAR(128) NOT NULL DEFAULT '',
  item_id         VARCHAR(64)  NOT NULL,
  mskus           VARCHAR(500) NOT NULL DEFAULT '' COMMENT '该item全部msku快照，/分隔',
  sku             VARCHAR(128) NOT NULL DEFAULT '' COMMENT '采购关联键',
