  `source_system`        VARCHAR(64)  NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `api_path`             VARCHAR(255) NOT NULL COMMENT '接口路径',
  `request_method`       VARCHAR(16)  NOT NULL DEFAULT 'GET' COMMENT '请求方法',
  `request_params_json`  JSON                  COMMENT '请求参数',
  `response_json`        JSON                  COMMENT '原始响应',
  `response_code`        VARCHAR(64)           COMMENT '响应码',
  `is_success`           TINYINT      NOT NULL DEFAULT 0 COMMENT '是否成功 1=是 0=否',
  `error_message`        TEXT                  COMMENT '错误信息',
  `data_date`            DATE                  COMMENT '数据日期',
  `pulled_at`            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '拉取时间',
  `raw_hash`             VARCHAR(64)           COMMENT '去重哈希 (md5)',
  `extra_json`           JSON                  COMMENT '扩展字段',
  `created_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_raw_lingxing` (`api_path`(200), `data_date`, `raw_hash`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW层: 领星API原始响应';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_feishu_table` (
  `id`                   BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `source_system`        VARCHAR(64)  NOT NULL DEFAULT 'feishu' COMMENT '来源系统',
  `app_token`            VARCHAR(128)          COMMENT '飞书 app_token',
  `spreadsheet_token`    VARCHAR(128) NOT NULL COMMENT '表格 token',
  `sheet_id`             VARCHAR(128) NOT NULL COMMENT 'sheet ID',
  `sheet_name`           VARCHAR(255)          COMMENT 'sheet 名称',
  `row_index`            INT          NOT NULL COMMENT '行号',
  `row_json`             JSON         NOT NULL COMMENT '原始行数据',
  `data_date`            DATE                  COMMENT '数据日期',
  `pulled_at`            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '拉取时间',
  `raw_hash`             VARCHAR(64)           COMMENT '去重哈希',
  `extra_json`           JSON                  COMMENT '扩展字段',
  `created_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_feishu_sheet` (`spreadsheet_token`(64), `sheet_id`(64), `data_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW层: 飞书表格原始数据';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_frontend_upload` (
  `id`             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `upload_type`    VARCHAR(64)  NOT NULL COMMENT '上传类型 (walmart_ads_csv / feishu_export / manual)',
  `file_name`      VARCHAR(255)          COMMENT '文件名',
  `file_path`      TEXT                  COMMENT '文件路径',
  `operator`       VARCHAR(128)          COMMENT '操作人',
  `source_tool`    VARCHAR(128)          COMMENT '来源工具',
  `upload_status`  VARCHAR(64)  NOT NULL DEFAULT 'pending' COMMENT '上传状态',
  `row_count`      INT                   COMMENT '行数',
  `uploaded_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `extra_json`     JSON                  COMMENT '扩展字段',
  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_upload_type_time` (`upload_type`, `uploaded_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW层: 前端上传文件记录';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_walmart_ads_csv` (
  `id`           BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `upload_id`    BIGINT                COMMENT '关联 raw_frontend_upload.id',
  `task_id`      VARCHAR(128)          COMMENT '任务ID',
  `row_index`    INT          NOT NULL COMMENT '行号',
  `row_json`     JSON         NOT NULL COMMENT '原始行数据',
  `report_date`  DATE                  COMMENT '报表日期',
