  COMMENT='RAW层: Walmart广告CSV前端上传原始行';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_store` (
  `id`             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `store_id`       VARCHAR(64)  NOT NULL COMMENT '平台侧店铺ID（必填）',
  `store_name`     VARCHAR(255)          COMMENT '店铺名称（展示用，不做唯一键）',
  `platform`       VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `country`        VARCHAR(64)           COMMENT '国家',
  `currency`       VARCHAR(16)           COMMENT '货币',
  `advertiser_id`  VARCHAR(64)           COMMENT '广告主ID',
  `owner`          VARCHAR(128)          COMMENT '负责人',
  `status`         VARCHAR(64)  NOT NULL DEFAULT 'active' COMMENT '状态',
  `source_system`  VARCHAR(64)  NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `extra_json`     JSON                  COMMENT '扩展字段',
  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dim_store` (`platform`, `store_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 店铺维度，唯一键=platform+store_id';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_product` (
  `product_key`      BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`         VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`         VARCHAR(64)  NOT NULL COMMENT '店铺ID（必填）',
  `store_name`       VARCHAR(255)          COMMENT '店铺名称（展示用）',
  `item_id`          VARCHAR(64)  NOT NULL COMMENT '商品ID',
  `msku`             VARCHAR(128) NOT NULL COMMENT 'MSKU',
  `sku`              VARCHAR(128)          COMMENT 'SKU',
  `asin`             VARCHAR(64)           COMMENT 'ASIN',
  `product_name`     TEXT                  COMMENT '商品名称',
  `item_name`        TEXT                  COMMENT '商品名称（平台侧）',
  `category`         VARCHAR(255)          COMMENT '分类',
  `brand`            VARCHAR(255)          COMMENT '品牌',
  `owner`            VARCHAR(128)          COMMENT '负责人',
  `status`           VARCHAR(64)  NOT NULL DEFAULT 'active' COMMENT '状态',
  `fulfillment_type` VARCHAR(64)           COMMENT '配送方式 (WFS/MFC)',
  `source_system`    VARCHAR(64)  NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `extra_json`       JSON                  COMMENT '扩展字段',
  `created_at`       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`product_key`),
  UNIQUE KEY `uq_dim_product` (`platform`, `store_id`, `item_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 商品维度';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_owner` (
  `owner_id`       BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `owner_name`     VARCHAR(128) NOT NULL COMMENT '姓名',
  `department`     VARCHAR(128)          COMMENT '部门',
