  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`owner_id`),
  UNIQUE KEY `uq_dim_owner` (`owner_name`, `department`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 负责人/人员维度';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_keyword` (
  `keyword_id`         BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `keyword_text`       VARCHAR(512) NOT NULL COMMENT '原始关键词',
  `normalized_keyword` VARCHAR(512) NOT NULL COMMENT '标准化关键词（小写+trim）',
  `keyword_type`       VARCHAR(64)  NOT NULL DEFAULT 'unknown'
                       COMMENT '类型: manual_keyword/auto_search_term/product_targeting/unknown',
  `platform`           VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `first_seen_at`      DATETIME              COMMENT '首次出现时间',
  `last_seen_at`       DATETIME              COMMENT '最近出现时间',
  `extra_json`         JSON                  COMMENT '扩展字段',
  `created_at`         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`         DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`keyword_id`),
  UNIQUE KEY `uq_dim_keyword` (`platform`, `normalized_keyword`(200), `keyword_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 关键词/搜索词维度';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_sales_daily` (
  `id`             BIGINT         NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date`      DATE           NOT NULL COMMENT '统计日期',
  `platform`       VARCHAR(64)    NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`       VARCHAR(64)    NOT NULL COMMENT '店铺ID',
  `store_name`     VARCHAR(255)            COMMENT '店铺名称（展示用）',
  `item_id`        VARCHAR(64)    NOT NULL COMMENT '商品ID',
  `msku`           VARCHAR(128)   NOT NULL COMMENT 'MSKU',
  `sku`            VARCHAR(128)            COMMENT 'SKU',
  `sales_qty`      INT            NOT NULL DEFAULT 0 COMMENT '销售数量',
  `order_count`    INT            NOT NULL DEFAULT 0 COMMENT '订单数',
  `sales_amount`   DECIMAL(18,4)  NOT NULL DEFAULT 0 COMMENT '销售金额',
  `refund_qty`     INT            NOT NULL DEFAULT 0 COMMENT '退款数量',
  `refund_amount`  DECIMAL(18,4)  NOT NULL DEFAULT 0 COMMENT '退款金额',
  `currency`       VARCHAR(16)             COMMENT '货币',
  `source_system`  VARCHAR(64)    NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id`  BIGINT                  COMMENT 'RAW层ID',
  `extra_json`     JSON                    COMMENT '扩展字段',
  `created_at`     DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`     DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_sales` (`stat_date`, `platform`, `store_id`, `item_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 每日销售事实表';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_inventory_daily` (
  `id`                  BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `snapshot_date`       DATE          NOT NULL COMMENT '快照日期',
  `platform`            VARCHAR(64)   NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`            VARCHAR(64)   NOT NULL COMMENT '店铺ID',
  `store_name`          VARCHAR(255)           COMMENT '店铺名称（展示用）',
  `item_id`             VARCHAR(64)   NOT NULL COMMENT '商品ID',
  `msku`                VARCHAR(128)  NOT NULL COMMENT 'MSKU',
  `sku`                 VARCHAR(128)           COMMENT 'SKU',
  `available_stock`     INT           NOT NULL DEFAULT 0 COMMENT '可用库存',
  `non_wfs_available_stock` INT       NOT NULL DEFAULT 0 COMMENT '非WFS可售库存',
  `wfs_available_stock` INT           NOT NULL DEFAULT 0 COMMENT 'WFS可用库存',
  `warehouse_stock`     INT           NOT NULL DEFAULT 0 COMMENT '仓库库存',
  `inbound_stock`       INT           NOT NULL DEFAULT 0 COMMENT '在途库存',
  `reserved_stock`      INT           NOT NULL DEFAULT 0 COMMENT '预留库存',
  `stock_days`          DECIMAL(18,4)          COMMENT '库存天数',
  `source_system`       VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id`       BIGINT                 COMMENT 'RAW层ID',
  `extra_json`          JSON                   COMMENT '扩展字段',
  `created_at`          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_inventory` (`snapshot_date`, `platform`, `store_id`, `item_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 每日库存事实表';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_product_daily` (
  `id`            BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date`     DATE          NOT NULL COMMENT '统计日期',
  `platform`      VARCHAR(64)   NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`      VARCHAR(64)   NOT NULL COMMENT '店铺ID',
