  `advertiser_id` VARCHAR(64)   NOT NULL COMMENT '广告主ID',
  `campaign_id`   VARCHAR(64)   NOT NULL COMMENT '广告活动ID',
  `campaign_name` VARCHAR(255)           COMMENT '广告活动名称',
  `campaign_type` VARCHAR(128)           COMMENT '广告类型 (SP/SB/SV)',
  `ad_group_id`   VARCHAR(64)   NOT NULL COMMENT '广告组ID',
  `ad_group_name` VARCHAR(255)           COMMENT '广告组名称',
  `item_id`       VARCHAR(64)   NOT NULL COMMENT '商品ID',
  `msku`          VARCHAR(128)           COMMENT 'MSKU',
  `impressions`   INT           NOT NULL DEFAULT 0 COMMENT '曝光量',
  `clicks`        INT           NOT NULL DEFAULT 0 COMMENT '点击量',
  `ctr`           DECIMAL(18,6)          COMMENT '点击率',
  `ad_spend`      DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '广告花费',
  `orders`        INT           NOT NULL DEFAULT 0 COMMENT '广告订单数',
  `total_sales`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '广告销售额',
  `acos`          DECIMAL(18,6)          COMMENT 'ACoS',
  `cpc`           DECIMAL(18,6)          COMMENT 'CPC',
  `cvr`           DECIMAL(18,6)          COMMENT '转化率',
  `roas`          DECIMAL(18,6)          COMMENT 'RoAS',
  `source_system` VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id` BIGINT                 COMMENT 'RAW层ID',
  `extra_json`    JSON                   COMMENT '扩展字段',
  `created_at`    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_ads_product` (`stat_date`, `platform`, `advertiser_id`, `campaign_id`, `ad_group_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 商品广告事实表';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_keyword_daily` (
  `id`                  BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date`           DATE          NOT NULL COMMENT '统计日期',
  `platform`            VARCHAR(64)   NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`            VARCHAR(64)   NOT NULL COMMENT '店铺ID（必填，不允许为空）',
  `store_name`          VARCHAR(255)           COMMENT '店铺名称（展示用）',
  `advertiser_id`       VARCHAR(64)            COMMENT '广告主ID',
  `campaign_id`         VARCHAR(64)            COMMENT '广告活动ID',
  `campaign_name`       VARCHAR(255)           COMMENT '广告活动名称',
  `campaign_type`       VARCHAR(128)           COMMENT '广告类型',
  `ad_group_id`         VARCHAR(64)            COMMENT '广告组ID',
  `ad_group_name`       VARCHAR(255)           COMMENT '广告组名称',
  `item_id`             VARCHAR(64)            COMMENT '商品ID',
  `item_name`           TEXT                   COMMENT '商品名称',
  `msku`                VARCHAR(128)           COMMENT 'MSKU',
  `keyword`             VARCHAR(512)  NOT NULL COMMENT '关键词原文',
  `normalized_keyword`  VARCHAR(512)  NOT NULL COMMENT '标准化关键词（小写+trim）',
  `match_type`          VARCHAR(64)   NOT NULL DEFAULT 'broad' COMMENT '匹配类型',
  `keyword_type`        VARCHAR(64)   NOT NULL DEFAULT 'unknown'
                        COMMENT '类型: manual_keyword/auto_search_term/product_targeting/unknown',
  `impressions`         INT           NOT NULL DEFAULT 0 COMMENT '曝光量',
  `clicks`              INT           NOT NULL DEFAULT 0 COMMENT '点击量',
  `ctr`                 DECIMAL(18,6)          COMMENT '点击率',
  `ad_spend`            DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '广告花费',
  `orders`              INT           NOT NULL DEFAULT 0 COMMENT '广告订单数',
  `conversion_rate`     DECIMAL(18,6)          COMMENT '转化率',
  `total_sales`         DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '广告销售额',
  `acos`                DECIMAL(18,6)          COMMENT 'ACoS',
  `cpc`                 DECIMAL(18,6)          COMMENT 'CPC',
  `cvr`                 DECIMAL(18,6)          COMMENT 'CVR',
  `roas`                DECIMAL(18,6)          COMMENT 'RoAS',
  `total_add_to_cart`   INT           NOT NULL DEFAULT 0 COMMENT '加购数量',
  `operator`            VARCHAR(128)           COMMENT '操作人',
  `source_type`         VARCHAR(64)   NOT NULL DEFAULT 'unknown'
                        COMMENT '数据来源: lingxing_keyword/walmart_auto_csv/frontend_auto_tool/feishu_manual/unknown',
  `source_system`       VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_task_id`      VARCHAR(128)           COMMENT '来源任务ID',
  `source_raw_id`       BIGINT                 COMMENT 'RAW层ID',
  `extra_json`          JSON                   COMMENT '扩展字段',
  `created_at`          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_ads_kw` (
    `stat_date`, `platform`, `store_id`, `item_id`(32),
    `normalized_keyword`(100), `match_type`, `source_type`
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 关键词/搜索词广告事实表，统一承接所有来源';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_profit_daily` (
  `id`             BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date`      DATE          NOT NULL COMMENT '统计日期',
  `platform`       VARCHAR(64)   NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`       VARCHAR(64)   NOT NULL COMMENT '店铺ID',
  `store_name`     VARCHAR(255)           COMMENT '店铺名称（展示用）',
  `item_id`        VARCHAR(64)   NOT NULL COMMENT '商品ID',
  `msku`           VARCHAR(128)  NOT NULL COMMENT 'MSKU',
  `sales_amount`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '销售额',
  `ad_spend`       DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '广告花费',
  `product_cost`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '货品成本',
  `logistics_cost` DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '物流成本',
  `platform_fee`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '平台费用',
  `refund_amount`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '退款金额',
  `gross_profit`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '毛利润',
  `net_profit`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '净利润',
  `profit_rate`    DECIMAL(18,6)          COMMENT '利润率',
  `source_system`  VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id`  BIGINT                 COMMENT 'RAW层ID',
