  `created_at`     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_profit` (`stat_date`, `platform`, `store_id`, `item_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 每日利润事实表';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_purchase_daily` (
  `id`                    BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchase_date`         DATE                   COMMENT '采购日期',
  `purchase_order_no`     VARCHAR(128)  NOT NULL COMMENT '采购单号',
  `supplier_id`           VARCHAR(64)            COMMENT '供应商ID',
  `supplier_name`         VARCHAR(255)           COMMENT '供应商名称',
  `platform`              VARCHAR(64)            COMMENT '平台',
  `store_id`              VARCHAR(64)            COMMENT '店铺ID',
  `item_id`               VARCHAR(64)            COMMENT '商品ID',
  `sku`                   VARCHAR(128)           COMMENT 'SKU',
  `msku`                  VARCHAR(128)           COMMENT 'MSKU',
  `purchase_qty`          INT           NOT NULL DEFAULT 0 COMMENT '采购数量',
  `received_qty`          INT           NOT NULL DEFAULT 0 COMMENT '已到货数量',
  `purchase_amount`       DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '采购金额',
  `status`                VARCHAR(64)   NOT NULL DEFAULT 'pending' COMMENT '状态',
  `expected_arrival_date` DATE                   COMMENT '预计到货日期',
  `source_system`         VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id`         BIGINT                 COMMENT 'RAW层ID',
  `extra_json`            JSON                   COMMENT '扩展字段',
  `created_at`            DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`            DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fact_purchase` (`purchase_order_no`, `sku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 采购事实表（预留）';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_event` (
  `event_id`    BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `event_date`  DATE         NOT NULL COMMENT '事件日期',
  `event_type`  VARCHAR(64)  NOT NULL
                COMMENT '类型: no_sales/low_stock/high_ad_spend/high_acos/profit_loss/purchase_delay/shipment_delay/owner_missing/data_mismatch',
  `severity`    VARCHAR(32)  NOT NULL DEFAULT 'warning' COMMENT '严重程度: info/warning/critical',
  `platform`    VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`    VARCHAR(64)           COMMENT '店铺ID',
  `store_name`  VARCHAR(255)          COMMENT '店铺名称（展示用）',
  `item_id`     VARCHAR(64)           COMMENT '商品ID',
  `msku`        VARCHAR(128)          COMMENT 'MSKU',
  `keyword`     VARCHAR(512)          COMMENT '关键词',
  `campaign_id` VARCHAR(64)           COMMENT '广告活动ID',
  `ad_group_id` VARCHAR(64)           COMMENT '广告组ID',
  `owner`       VARCHAR(128)          COMMENT '负责人',
  `title`       VARCHAR(255) NOT NULL COMMENT '事件标题',
  `reason`      TEXT                  COMMENT '触发原因',
  `suggestion`  TEXT                  COMMENT '处理建议',
  `status`      VARCHAR(64)  NOT NULL DEFAULT 'open' COMMENT '状态: open/processing/resolved/ignored',
  `source_table` VARCHAR(128)         COMMENT '来源表',
  `source_key`  VARCHAR(255)          COMMENT '来源记录标识',
  `detected_by` VARCHAR(64)           COMMENT '检测方式 (rule/ai/manual)',
  `extra_json`  JSON                  COMMENT '扩展字段',
  `created_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `resolved_at` DATETIME              COMMENT '解决时间',
  PRIMARY KEY (`event_id`),
  UNIQUE KEY `uq_biz_event` (`event_date`, `event_type`, `source_key`(200)),
  KEY `idx_event_store_date` (`store_id`, `event_date`),
  KEY `idx_event_status` (`status`, `event_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='EVENT层: 统一业务事件（断销/预警/异常/任务流）';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `ai_analysis_result` (
  `analysis_id`         BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `analysis_date`       DATE          NOT NULL COMMENT '分析日期',
  `analysis_type`       VARCHAR(64)   NOT NULL
                        COMMENT '类型: sales_analysis/ads_keyword_analysis/inventory_analysis/profit_analysis/purchase_analysis',
  `platform`            VARCHAR(64)            COMMENT '平台',
  `store_id`            VARCHAR(64)            COMMENT '店铺ID',
  `item_id`             VARCHAR(64)            COMMENT '商品ID',
  `msku`                VARCHAR(128)           COMMENT 'MSKU',
  `keyword`             VARCHAR(512)           COMMENT '关键词',
  `input_snapshot_json` JSON          NOT NULL COMMENT '分析输入快照',
  `model_name`          VARCHAR(128)  NOT NULL COMMENT '模型名称',
  `prompt_version`      VARCHAR(64)   NOT NULL DEFAULT 'v1' COMMENT '提示词版本',
  `result_json`         JSON          NOT NULL COMMENT '分析结果（结构化）',
  `conclusion`          TEXT                   COMMENT '结论',
  `recommendation`      TEXT                   COMMENT '建议',
  `risk_score`          DECIMAL(18,6)          COMMENT '风险评分 0~1',
  `confidence`          DECIMAL(18,6)          COMMENT '置信度 0~1',
  `source_event_id`     BIGINT                 COMMENT '关联 biz_event.event_id',
  `extra_json`          JSON                   COMMENT '扩展字段',
  `created_at`          DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`analysis_id`),
  KEY `idx_ai_date_type` (`analysis_date`, `analysis_type`),
  KEY `idx_ai_store_item` (`store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI层: AI分析结果，AI只写此表，不直接修改FACT/DIM';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `sync_task_log` (
  `task_id`        BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_name`      VARCHAR(128) NOT NULL COMMENT '任务名称',
  `source_system`  VARCHAR(64)           COMMENT '来源系统',
  `target_table`   VARCHAR(128)          COMMENT '目标表',
  `started_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `finished_at`    DATETIME              COMMENT '结束时间',
  `status`         VARCHAR(64)  NOT NULL DEFAULT 'running' COMMENT '状态: running/success/failed',
  `pulled_count`   INT          NOT NULL DEFAULT 0 COMMENT '拉取行数',
  `inserted_count` INT          NOT NULL DEFAULT 0 COMMENT '插入行数',
  `updated_count`  INT          NOT NULL DEFAULT 0 COMMENT '更新行数',
  `failed_count`   INT          NOT NULL DEFAULT 0 COMMENT '失败行数',
  `error_message`  TEXT                  COMMENT '错误信息',
  `extra_json`     JSON                  COMMENT '扩展字段',
  PRIMARY KEY (`task_id`),
  KEY `idx_sync_task_name` (`task_name`, `started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='系统: 同步任务运行日志';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `data_reconcile_log` (
  `id`              BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `reconcile_date`  DATE          NOT NULL COMMENT '对账日期',
  `metric_name`     VARCHAR(128)  NOT NULL COMMENT '指标名称',
  `platform`        VARCHAR(64)            COMMENT '平台',
  `store_id`        VARCHAR(64)            COMMENT '店铺ID',
  `item_id`         VARCHAR(64)            COMMENT '商品ID',
  `msku`            VARCHAR(128)           COMMENT 'MSKU',
  `mysql_value`     DECIMAL(18,6)          COMMENT 'MySQL数据值',
  `feishu_value`    DECIMAL(18,6)          COMMENT '飞书数据值',
  `api_value`       DECIMAL(18,6)          COMMENT 'API数据值',
  `diff_value`      DECIMAL(18,6)          COMMENT '差值',
  `diff_rate`       DECIMAL(18,6)          COMMENT '差异率',
  `status`          VARCHAR(64)   NOT NULL DEFAULT 'pending' COMMENT '状态: pending/matched/mismatch/ignored',
  `reason`          TEXT                   COMMENT '差异原因',
  `extra_json`      JSON                   COMMENT '扩展字段',
  `created_at`      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_reconcile_date` (`reconcile_date`, `metric_name`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='系统: 数据对账日志';

-- source: sql/001_create_data_warehouse_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `schema_change_log` (
  `id`             BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `table_name`     VARCHAR(128) NOT NULL COMMENT '表名',
  `column_name`    VARCHAR(128)          COMMENT '字段名',
  `change_type`    VARCHAR(64)  NOT NULL
                   COMMENT '类型: add_table/add_column/modify_column/deprecate_column/drop_column_request/index_change',
  `old_definition` TEXT                  COMMENT '旧定义',
  `new_definition` TEXT                  COMMENT '新定义',
  `reason`         TEXT         NOT NULL COMMENT '变更原因',
  `changed_by`     VARCHAR(128) NOT NULL DEFAULT 'system' COMMENT '变更人',
  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_schema_change_table` (`table_name`, `created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='系统: 表结构变更记录（必须严格执行）';

