-- source: sql/003_product_identity_owner_cost_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_product_identity` (
  `id`                   BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`             VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '店铺ID（可为空串）',
  `store_name`           VARCHAR(255) NOT NULL DEFAULT '' COMMENT '店铺名称',
  `item_id`              VARCHAR(64)  NOT NULL COMMENT '平台商品ID',
  `msku`                 VARCHAR(128) NOT NULL COMMENT 'MSKU',
  `sku`                  VARCHAR(128)          COMMENT 'SKU',
  `local_sku`            VARCHAR(128)          COMMENT '本地SKU',
  `lingxing_product_id`  VARCHAR(128)          COMMENT '领星产品ID',
  `source_system`        VARCHAR(64)  NOT NULL DEFAULT 'feishu_item_owner' COMMENT '来源系统',
  `source_raw_id`        VARCHAR(128)          COMMENT '原始数据 raw_hash',
  `confidence`           TINYINT      NOT NULL DEFAULT 100 COMMENT '置信度 0-100',
  `status`               VARCHAR(64)  NOT NULL DEFAULT 'active' COMMENT '状态',
  `extra_json`           JSON                  COMMENT '扩展字段',
  `created_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dim_product_identity` (`platform`, `store_name`(64), `item_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 商品身份映射（ItemID/MSKU/SKU 统一映射）';

-- source: sql/003_product_identity_owner_cost_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_product_owner` (
  `id`              BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`        VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`        VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '店铺ID（可为空串）',
  `store_name`      VARCHAR(255) NOT NULL DEFAULT '' COMMENT '店铺名称',
  `item_id`         VARCHAR(64)  NOT NULL COMMENT '平台商品ID',
  `msku`            VARCHAR(128) NOT NULL COMMENT 'MSKU',
  `owner_name`      VARCHAR(128) NOT NULL COMMENT '负责人姓名',
  `owner_id`        BIGINT                COMMENT '关联 dim_owner.owner_id',
  `feishu_user_id`  VARCHAR(128)          COMMENT '飞书用户ID',
  `effective_date`  DATE         NOT NULL COMMENT '生效日期',
  `status`          VARCHAR(64)  NOT NULL DEFAULT 'active' COMMENT '状态 active/inactive',
  `source_system`   VARCHAR(64)  NOT NULL DEFAULT 'feishu_item_owner' COMMENT '来源系统',
  `source_raw_id`   VARCHAR(128)          COMMENT '原始数据 raw_hash',
  `extra_json`      JSON                  COMMENT '扩展字段',
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dim_product_owner` (`platform`, `store_name`(64), `item_id`, `msku`(64), `owner_name`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 商品负责人关系（支持历史变更）';

-- source: sql/003_product_identity_owner_cost_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_product_cost_config` (
  `id`               BIGINT         NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`         VARCHAR(64)    NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`         VARCHAR(64)    NOT NULL DEFAULT '' COMMENT '店铺ID（可为空串）',
  `store_name`       VARCHAR(255)   NOT NULL DEFAULT '' COMMENT '店铺名称',
  `item_id`          VARCHAR(64)    NOT NULL COMMENT '平台商品ID',
  `msku`             VARCHAR(128)   NOT NULL COMMENT 'MSKU',
  `sku`              VARCHAR(128)            COMMENT 'SKU',
  `delivery_fee`     DECIMAL(10,4)           COMMENT 'WFS/FBW 配送费（$）',
  `shipping_fee`     DECIMAL(10,4)           COMMENT '物流运费（$）',
  `purchase_cost`    DECIMAL(10,4)           COMMENT '采购成本（$）',
  `logistics_cost`   DECIMAL(10,4)           COMMENT '头程物流费（$）',
  `effective_date`   DATE           NOT NULL COMMENT '生效日期',
  `status`           VARCHAR(64)    NOT NULL DEFAULT 'active' COMMENT '状态',
  `source_system`    VARCHAR(64)    NOT NULL DEFAULT 'feishu_item_owner' COMMENT '来源系统',
  `source_raw_id`    VARCHAR(128)            COMMENT '原始数据 raw_hash',
  `extra_json`       JSON                    COMMENT '扩展字段',
  `created_at`       DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`       DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dim_product_cost` (`platform`, `store_name`(64), `item_id`, `msku`(64), `effective_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: 商品成本/配送费配置';

