-- source: sql/005_raw_sync_tasks.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_sync_tasks` (
  `id`              BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',
  `sync_task_id`    VARCHAR(64)   NOT NULL COMMENT '任务唯一ID (UUID)',
  `source_type`     VARCHAR(64)   NOT NULL DEFAULT 'feishu' COMMENT '来源类型',
  `source_name`     VARCHAR(128)           COMMENT '来源名称',
  `sheet_id`        VARCHAR(128)           COMMENT '飞书 Sheet ID',
  `sheet_name`      VARCHAR(255)           COMMENT '飞书 Sheet 名称',
  `status`          VARCHAR(32)   NOT NULL DEFAULT 'running' COMMENT 'running/success/failed',
  `row_count`       INT                    COMMENT '飞书总行数',
  `inserted_count`  INT           NOT NULL DEFAULT 0 COMMENT '新增行数',
  `updated_count`   INT           NOT NULL DEFAULT 0 COMMENT '更新行数',
  `skipped_count`   INT           NOT NULL DEFAULT 0 COMMENT '跳过行数',
  `started_at`      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `finished_at`     DATETIME               COMMENT '完成时间',
  `error_message`   TEXT                   COMMENT '错误信息',
  `created_at`      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_rst_task_id`  (`sync_task_id`),
  KEY `idx_rst_sheet`    (`source_type`, `sheet_id`, `started_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW层: 同步任务日志';

