-- source: sql/007_cs_test_product_config.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `cs_test_product_config` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `config_type` VARCHAR(64) NOT NULL COMMENT '配置类型',
  `config_key` VARCHAR(128) NOT NULL COMMENT '配置项',
  `config_value` TEXT NOT NULL COMMENT '配置值',
  `description` TEXT NULL COMMENT '说明',
  `enabled` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cs_test_product_config` (`config_type`, `config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CS测品分析Beta配置表';

-- source: sql/009_ads_platform_pagetype_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_platform_daily` (
  `id`                   BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键',

  
  `stat_date`            DATE          NOT NULL                COMMENT '统计日期',
  `platform`             VARCHAR(64)   NOT NULL DEFAULT 'walmart'
                                                              COMMENT '电商平台，固定值 walmart',
  `store_id`             VARCHAR(64)   NOT NULL                COMMENT '店铺ID（映射自 dim_store）',
  `store_name`           VARCHAR(255)                          COMMENT '店铺名称（展示用，冗余）',
  `advertiser_id`        VARCHAR(64)   NOT NULL                COMMENT '广告主ID (advertiserId)',
  `advertiser_name`      VARCHAR(255)                          COMMENT '广告主名称 (mpAdvertiserName)',
  `campaign_id`          VARCHAR(64)   NOT NULL                COMMENT '广告活动ID',
  `campaign_name`        VARCHAR(255)                          COMMENT '广告活动名称',
  `campaign_status`      VARCHAR(64)                           COMMENT '活动状态: enabled/paused/live/completed等',
  `campaign_type`        VARCHAR(64)                           COMMENT '广告类型: sponsoredProducts/sba/video',
  `ad_group_id`          VARCHAR(64)   NOT NULL                COMMENT '广告组ID',
  `ad_group_name`        VARCHAR(255)                          COMMENT '广告组名称',
  `ad_platform`          VARCHAR(64)   NOT NULL                COMMENT '投放平台: Desktop / Mobile',
  `bid`                  DECIMAL(18,4)                         COMMENT '当前竞价 ($)',

  
  `impressions`          INT           NOT NULL DEFAULT 0      COMMENT '曝光量 (numAdsShown)',
  `clicks`               INT           NOT NULL DEFAULT 0      COMMENT '点击量 (numAdsClicks)',
  `ad_spend`             DECIMAL(18,4) NOT NULL DEFAULT 0      COMMENT '广告花费 ($)',

  
  `orders`               INT           NOT NULL DEFAULT 0      COMMENT '归因广告订单数',
  `total_sales`          DECIMAL(18,4) NOT NULL DEFAULT 0      COMMENT '归因广告销售额 ($)',
  `units`                INT           NOT NULL DEFAULT 0      COMMENT '归因广告销量',
  `advertised_sku_sales` DECIMAL(18,4) NOT NULL DEFAULT 0      COMMENT '直接归因销售额 ($)',
  `advertised_sku_units` INT           NOT NULL DEFAULT 0      COMMENT '直接归因销量',
  `other_sku_sales`      DECIMAL(18,4) NOT NULL DEFAULT 0      COMMENT '间接/关联销售额 ($)',
  `other_sku_units`      INT           NOT NULL DEFAULT 0      COMMENT '间接/关联销量',

  
  `ctr`                  DECIMAL(18,6)                         COMMENT '点击率 CTR (%)',
  `cpc`                  DECIMAL(18,6)                         COMMENT '点击成本 CPC ($)',
  `cvr`                  DECIMAL(18,6)                         COMMENT '转化率 CVR (%)',
  `acos`                 DECIMAL(18,6)                         COMMENT 'ACoS (%)',
  `roas`                 DECIMAL(18,6)                         COMMENT 'RoAS',
  `aov`                  DECIMAL(18,4)                         COMMENT '平均订单值 AOV ($)',
  `cpa`                  DECIMAL(18,4)                         COMMENT '平均订单成本 CPA ($)',

  
  `ntb_orders`           INT           NOT NULL DEFAULT 0      COMMENT '品牌新买家订单数',
  `ntb_revenue`          DECIMAL(18,4) NOT NULL DEFAULT 0      COMMENT '品牌新买家销售额 ($)',
  `ntb_units`            INT           NOT NULL DEFAULT 0      COMMENT '品牌新买家销量',
  `ntb_order_rate`       DECIMAL(18,6)                         COMMENT '品牌新买家订单转化率 (%)',
  `ntb_orders_pct`       DECIMAL(18,6)                         COMMENT '新买家订单占比 (%)',
  `ntb_revenue_pct`      DECIMAL(18,6)                         COMMENT '新买家销售额占比 (%)',
  `ntb_units_pct`        DECIMAL(18,6)                         COMMENT '新买家销量占比 (%)',

  
  `source_system`        VARCHAR(64)   NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id`        BIGINT                                COMMENT 'RAW层ID (raw_lingxing_api.id)',
  `extra_json`           JSON                                  COMMENT '扩展字段（含 inStore* 实体店低频数据）',
  `created_at`           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`           DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
                                       ON UPDATE CURRENT_TIMESTAMP,

  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ads_platform` (
    `stat_date`, `platform`, `store_id`, `advertiser_id`, `campaign_id`, `ad_group_id`, `ad_platform`
  ),
  KEY `idx_stat_date`   (`stat_date`),
  KEY `idx_store_date`  (`store_id`, `stat_date`),
  KEY `idx_campaign`    (`campaign_id`, `stat_date`),
  KEY `idx_ad_platform` (`ad_platform`, `stat_date`)

) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: SP广告-平台维度事实表 | reportPlatformSpList | 粒度: 日+平台+店铺+活动+广告组+Desktop/Mobile';

-- source: sql/009_create_dim_store_config.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_store_config` (
  `id`              BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`        VARCHAR(64)  NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`        VARCHAR(64)  NOT NULL COMMENT '领星店铺ID',
  `store_name`      VARCHAR(255)          COMMENT '店铺名称',
  `advertiser_id`   VARCHAR(64)           COMMENT '广告主ID（无广告账户则空）',
  `advertiser_name` VARCHAR(255)          COMMENT '广告主名称',
  `is_active`       TINYINT      NOT NULL DEFAULT 1 COMMENT '是否纳入同步：1是 0否',
  `auth_status`     VARCHAR(32)           COMMENT '领星店铺授权状态：normal/expired/failed',
  `commission_rate` DECIMAL(6,4)          COMMENT '交易费率（如 0.12）',
  `source`          VARCHAR(64)  NOT NULL DEFAULT 'lingxing' COMMENT '来源',
  `first_seen_at`   DATETIME              COMMENT '首次发现时间',
  `last_seen_at`    DATETIME              COMMENT '最近一次在领星出现的时间',
  `created_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dim_store_config` (`platform`, `store_id`),
  KEY `idx_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='店铺自动发现与同步配置，唯一键=platform+store_id';

-- source: sql/010_product_management_status.sql; type: ALTER TABLE
ALTER TABLE `dim_product`
  ADD COLUMN `product_management_status` VARCHAR(20) NOT NULL DEFAULT 'active'
    COMMENT '产品管理状态: active在用/inactive停用/archived归档',
  ADD COLUMN `product_management_status_source` VARCHAR(20) NOT NULL DEFAULT 'system'
    COMMENT '状态来源: system系统判断/manual人工操作',
  ADD COLUMN `product_management_status_reason` VARCHAR(255) NULL
    COMMENT '产品管理状态原因',
  ADD COLUMN `product_management_status_updated_at` DATETIME NULL
    COMMENT '产品管理状态更新时间',
  ADD INDEX `idx_dim_product_pm_status` (`product_management_status`);

-- source: sql/010_wfs_shipment_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_wfs_shipment` (
  `id`                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`           VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  `store_id`           VARCHAR(64)  NOT NULL,
  `store_name`         VARCHAR(128) NOT NULL DEFAULT '',
  `shipment_id`        VARCHAR(64)  NOT NULL COMMENT '领星WFS货件id（records.id）',
  `cargo_code`         VARCHAR(128) NOT NULL DEFAULT '' COMMENT '货件单号',
  `inbound_order_id`   VARCHAR(128) NOT NULL DEFAULT '' COMMENT '入库订单编号',
  `status`             TINYINT      NOT NULL COMMENT '0待发货详情 1待送达 2接收中 3已关闭 4已取消',
  `status_name`        VARCHAR(64)  NOT NULL DEFAULT '',
  `cargo_status`       VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '平台货件状态文本',
  `cargo_sync_status`  VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '货件本地状态（如 已申报）',
  `logistics_code`     VARCHAR(64)  NOT NULL DEFAULT '',
  `cargo_create_date`  DATETIME     NULL,
  `to_pending_time`    DATETIME     NULL COMMENT '进入PENDING_SHIPMENT_DETAILS时间',
  `to_await_time`      DATETIME     NULL COMMENT '进入AWAITING_DELIVERY时间',
  `to_receive_time`    DATETIME     NULL COMMENT '进入RECEIVING_IN_PROGRESS时间（R1触发）',
  `to_closed_time`     DATETIME     NULL COMMENT '进入CLOSED时间（R3窗口起点）',
  `to_cancelled_time`  DATETIME     NULL,
  `cargo_update_date`  DATETIME     NULL COMMENT 'API update_date',
  `system_update_date` DATETIME     NULL COMMENT 'API system_update_date（probe实测新增，增量锚点）',
  `source_raw_id`      BIGINT UNSIGNED NULL COMMENT 'raw_lingxing_api.id 留痕回溯',
  `created_at`         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wfs_shipment` (`platform`, `store_id`, `shipment_id`),
  KEY `idx_wfs_shipment_status` (`status`),
  KEY `idx_wfs_shipment_closed` (`to_closed_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='WFS货件头快照（领星queryWFSCargoPage，UPSERT覆盖状态列）';

-- source: sql/010_wfs_shipment_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_wfs_shipment_item` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`       VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `shipment_id`    VARCHAR(64)  NOT NULL,
  `msku`           VARCHAR(255) NOT NULL DEFAULT '',
  `sku`            VARCHAR(255) NOT NULL DEFAULT '',
  `gtin`           VARCHAR(64)  NOT NULL DEFAULT '',
  `product_name`   VARCHAR(512) NOT NULL DEFAULT '',
  `declare_num`    INT NOT NULL DEFAULT 0 COMMENT '申报量（安全转数，禁止NaN/负值直写）',
  `shipments_num`  INT NOT NULL DEFAULT 0 COMMENT '已发货数量',
  `received_num`   INT NOT NULL DEFAULT 0 COMMENT '签收数量',
  `damaged_qty`    INT NOT NULL DEFAULT 0 COMMENT '损坏数量（API字段拼写为dameged_qty）',
  `source_raw_id`  BIGINT UNSIGNED NULL,
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wfs_shipment_item` (`platform`, `store_id`, `shipment_id`, `msku`(64)),
  KEY `idx_wfs_item_msku` (`platform`, `store_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='WFS货件商品明细（负责人/广告判定经 store_id+msku 关联 dim_product）';

-- source: sql/010_wfs_shipment_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_arrival_notify` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `event_type`    VARCHAR(64)  NOT NULL,
  `biz_key`       VARCHAR(255) NOT NULL COMMENT '业务幂等键，同一事件只存在一行',
  `event_date`    DATE         NOT NULL COMMENT '事件业务日期（上海口径）',
  `platform`      VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  `store_id`      VARCHAR(64)  NOT NULL DEFAULT '',
  `item_id`       VARCHAR(64)  NOT NULL DEFAULT '',
  `msku`          VARCHAR(255) NOT NULL DEFAULT '',
  `shipment_id`   VARCHAR(64)  NOT NULL DEFAULT '',
  `owner`         VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '事件生成时的 dim_product.owner 快照',
  `payload_json`  JSON         NULL COMMENT '文案要素：数量对比/无广告天数/第M次提醒等',
  `notify_status` VARCHAR(16)  NOT NULL DEFAULT 'pending' COMMENT 'pending/notified/skipped/failed',
  `notified_at`   DATETIME     NULL,
  `notify_error`  VARCHAR(512) NOT NULL DEFAULT '',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_arrival_event` (`event_type`, `biz_key`),
  KEY `idx_arrival_pending` (`notify_status`, `event_date`),
  KEY `idx_arrival_shipment` (`shipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='到货提醒事件（生成方：syncWfsShipments/buildArrivalEvents；回写方：arrivalNotify 仅改 notify_*）';

-- source: sql/011_biz_product_rule_signal_daily.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_product_rule_signal_daily` (
  `id`                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `signal_date`           DATE            NOT NULL COMMENT '信号业务日 = dim_product_business_state.stat_date',
  `platform`              VARCHAR(32)     NOT NULL DEFAULT 'walmart',
  `store_id`              VARCHAR(64)     NOT NULL DEFAULT '',
  `store_name`            VARCHAR(128)    NOT NULL DEFAULT '',
  `store_key`             VARCHAR(128)    NOT NULL COMMENT '唯一键锚点：store_id 优先，否则 store_name',
  `item_id`               VARCHAR(64)     NOT NULL DEFAULT '',
  `msku`                  VARCHAR(128)    NOT NULL DEFAULT '',
  `owner`                 VARCHAR(128)             DEFAULT NULL,
  `product_type`          VARCHAR(32)     NOT NULL COMMENT 'cs_test / regular',
  `rule_group`            VARCHAR(32)     NOT NULL COMMENT 'profit / inventory / ad / cs',
  `rule_code`             VARCHAR(64)     NOT NULL,
  `rule_name`             VARCHAR(128)    NOT NULL,
  `rule_level`            VARCHAR(32)     NOT NULL COMMENT 'info / warning / critical / positive',
  `trigger_reason`        TEXT,
  `suggested_action`      TEXT,
  `notify_frequency_days` INT                      DEFAULT NULL COMMENT '规则静态属性；真正去重留第5期',
  `should_notify`         TINYINT(1)      NOT NULL DEFAULT 0 COMMENT 'v1 仅表示今日触发，非今日应发送',
  `source_metrics_json`   JSON                     DEFAULT NULL,
  `source_state_date`     DATE                     DEFAULT NULL,
  `source_state_id`       BIGINT                   DEFAULT NULL,
  `ad_window_start`       DATE                     DEFAULT NULL COMMENT 'CS 规则近3天窗口起（实际业务日）',
  `ad_window_end`         DATE                     DEFAULT NULL COMMENT 'CS 规则近3天窗口止（实际业务日）',
  `signal_source`         VARCHAR(32)     NOT NULL DEFAULT 'system_rule',
  `rule_version`          VARCHAR(32)     NOT NULL DEFAULT 'v1',
  `created_at`            DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`            DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_signal_day` (`signal_date`,`platform`,`store_key`,`item_id`,`msku`,`rule_code`),
  KEY `idx_signal_date` (`signal_date`),
  KEY `idx_rule_code` (`rule_code`),
  KEY `idx_store_item` (`store_id`,`item_id`),
  KEY `idx_owner` (`owner`),
  KEY `idx_should_notify` (`signal_date`,`should_notify`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务H-1E 系统规则信号日快照';

-- source: sql/012_order_drop_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_sales_orders_early` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `stat_date`     DATE        NOT NULL COMMENT '订单归属日（saleStat date_collect 键，站点时区口径，观察期核验）',
  `platform`      VARCHAR(20) NOT NULL DEFAULT 'walmart',
  `store_id`      VARCHAR(64) NOT NULL,
  `item_id`       VARCHAR(64) NOT NULL,
  `order_count`   INT         NOT NULL DEFAULT 0 COMMENT '订单量（result_type=2）',
  `pull_slot`     VARCHAR(8)  NOT NULL DEFAULT '1625' COMMENT '拉取时点：1625=正式 / 2000=观察期完整度对照',
  `source_raw_id` BIGINT UNSIGNED NULL COMMENT 'raw_lingxing_api.id 留痕',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_early` (`stat_date`, `platform`, `store_id`, `item_id`, `pull_slot`),
  KEY `idx_orders_early_item` (`platform`, `store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='订单下滑提醒专用早鸟订单快照（16:25拉取；禁止写入fact_sales_daily）';

-- source: sql/015_event_clearance_approval.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_clearance_approval (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  platform        VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id        VARCHAR(64)  NOT NULL,
  store_name      VARCHAR(128) NOT NULL DEFAULT '',
  item_id         VARCHAR(64)  NOT NULL,
  mskus           VARCHAR(500) NOT NULL DEFAULT '' COMMENT '该item全部msku快照，/分隔',
  sku             VARCHAR(128) NOT NULL DEFAULT '' COMMENT '采购关联键',
  owner           VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '产品负责人（申请时快照）',
  applicant       VARCHAR(64)  NOT NULL COMMENT '页面操作人 operator_name',
  metrics_json    JSON NULL COMMENT '申请时快照：sales30/stock/inbound/turnoverDays',
  status          ENUM('pending','approved','rejected','cancelled','legacy')
                  NOT NULL DEFAULT 'pending',
  approver        VARCHAR(64) NULL,
  decided_at      DATETIME NULL,
  reject_reason   VARCHAR(200) NOT NULL DEFAULT '',
  notify_count    INT NOT NULL DEFAULT 0 COMMENT '进入09:33汇总卡的次数',
  last_notified_at DATETIME NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_status (status),
  KEY idx_item (platform, store_id, item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='清货期审批事件（EVENT层）';

-- source: sql/016_clearance_center.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_clearance_other_channel (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  platform      VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id      VARCHAR(64)  NOT NULL DEFAULT '',
  store_name    VARCHAR(128) NOT NULL DEFAULT '',
  item_id       VARCHAR(64)  NOT NULL,
  mskus         VARCHAR(500) NOT NULL DEFAULT '',
  sku           VARCHAR(128) NOT NULL DEFAULT '',
  owner         VARCHAR(64)  NOT NULL DEFAULT '',
  channel_note  VARCHAR(200) NOT NULL COMMENT '清货渠道（人工填写，同步不得覆盖）',
  amazon_asin   VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '批⑤亚马逊销量匹配：人工填写优先于SKU自动匹配',
  status        ENUM('active','done','removed') NOT NULL DEFAULT 'active',
  added_by      VARCHAR(64)  NOT NULL DEFAULT '',
  remark        VARCHAR(500) NOT NULL DEFAULT '',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_item (platform, store_id, item_id),
  KEY idx_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='其他渠道清货台账（人工维护，清货中心批②）';

-- source: sql/017_clearance_other_channel_v2.sql; type: CREATE TABLE
CREATE TABLE biz_clearance_other_channel (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  sku           VARCHAR(128) NOT NULL COMMENT '公司SKU（台账主键维度）',
  mskus         VARCHAR(500) NOT NULL DEFAULT '' COMMENT 'dim_product 同SKU的msku快照，/分隔',
  owner         VARCHAR(64)  NOT NULL COMMENT '负责人（人工填写）',
  channel       VARCHAR(20)  NOT NULL COMMENT '清货渠道：亚马逊/希音（后续可扩展）',
  platform_ref  VARCHAR(64)  NOT NULL COMMENT '平台识别号：亚马逊=ASIN，希音=平台SKC',
  manual_stock  INT          NOT NULL DEFAULT 0 COMMENT '渠道库存数量（人工填写维护）',
  status        ENUM('active','done','removed') NOT NULL DEFAULT 'active',
  added_by      VARCHAR(64)  NOT NULL DEFAULT '',
  remark        VARCHAR(500) NOT NULL DEFAULT '',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_sku_channel (sku, channel),
  KEY idx_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='其他渠道清货台账v2（SKU维度，人工维护；owner/channel/platform_ref/manual_stock/remark 禁止同步覆盖）';

-- source: sql/018_clearance_expect_date.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_clearance_expect_date (
  row_key     VARCHAR(200) NOT NULL PRIMARY KEY,
  expect_end  DATE NOT NULL COMMENT '预计清货结束时间（人工选择）',
  updated_by  VARCHAR(64) NOT NULL DEFAULT '',
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='清货预计结束时间（人工维护，清货中心批②v4）';

-- source: sql/019_event_clearance_card.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_clearance_card (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  card_type      ENUM('tail','archive','revive') NOT NULL,
  platform       VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id       VARCHAR(64)  NOT NULL,
  store_name     VARCHAR(128) NOT NULL DEFAULT '',
  item_id        VARCHAR(64)  NOT NULL,
  mskus          VARCHAR(500) NOT NULL DEFAULT '',
  sku            VARCHAR(128) NOT NULL DEFAULT '',
  owner          VARCHAR(64)  NOT NULL DEFAULT '',
  biz_key        VARCHAR(200) NOT NULL COMMENT 'tail/archive:type:store:item:发送日；revive:type:shipment:store:item',
  metrics_json   JSON NULL COMMENT '发送时快照：stock/daily7/daysToClear/zeroDays/shipmentId等',
  status         ENUM('sent','acted','failed') NOT NULL DEFAULT 'sent',
  action         VARCHAR(32) NOT NULL DEFAULT '' COMMENT '继续清货/转稳定期/转上升期/确认归档/暂不归档',
  acted_by       VARCHAR(64) NULL,
  acted_at       DATETIME NULL,
  suppress_until DATE NULL COMMENT '抑制截止：继续清货+14天，暂不归档+7天',
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_type_key (card_type, biz_key),
  KEY idx_item (card_type, store_id, item_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='清货自动卡事件（EVENT层，批③）';

-- source: sql/020_purchase_order.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_purchase_order (
  id                  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  order_sn            VARCHAR(64)  NOT NULL,
  status              VARCHAR(16)  NOT NULL DEFAULT '',
  status_text         VARCHAR(32)  NOT NULL DEFAULT '',
  status_shipped      VARCHAR(16)  NOT NULL DEFAULT '',
  status_shipped_text VARCHAR(32)  NOT NULL DEFAULT '',
  ware_house_name     VARCHAR(128) NOT NULL DEFAULT '',
  order_time          VARCHAR(32)  NOT NULL DEFAULT '',
  create_time         VARCHAR(32)  NOT NULL DEFAULT '',
  auditor_time        VARCHAR(32)  NOT NULL DEFAULT '',
  update_time         VARCHAR(32)  NOT NULL DEFAULT '',
  source_raw_id       BIGINT UNSIGNED NULL,
  created_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_order (order_sn),
  KEY idx_status (status_text)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='领星采购单头（FACT，批④）';

-- source: sql/020_purchase_order.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_purchase_order_item (
  id                 BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  order_sn           VARCHAR(64)  NOT NULL,
  sku                VARCHAR(128) NOT NULL DEFAULT '',
  msku               VARCHAR(128) NOT NULL DEFAULT '',
  product_name       VARCHAR(255) NOT NULL DEFAULT '',
  quantity_real      INT NOT NULL DEFAULT 0 COMMENT '计划采购量',
  quantity_entry     INT NOT NULL DEFAULT 0,
  quantity_receive   INT NOT NULL DEFAULT 0 COMMENT '已收货量',
  expect_arrive_time VARCHAR(32) NOT NULL DEFAULT '',
  source_raw_id      BIGINT UNSIGNED NULL,
  created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_order_sku (order_sn, sku, msku),
  KEY idx_sku (sku)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='领星采购单明细（FACT，批④）';

-- source: sql/021_local_inventory.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_local_inventory_daily (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  snapshot_date DATE NOT NULL COMMENT '拉取当日（实时库存打拉取日标签，同 fact_inventory_daily 口径教训）',
  sku           VARCHAR(128) NOT NULL,
  qty           INT NOT NULL DEFAULT 0 COMMENT '本地仓可用库存（字段侦测：product_valid_num 等候选）',
  source_raw_id BIGINT UNSIGNED NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_date_sku (snapshot_date, sku),
  KEY idx_sku (sku)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='本地仓库存每日快照（FACT，批④v3）';

-- source: sql/022_app_auth_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS dim_app_user (
  id                   INT UNSIGNED NOT NULL AUTO_INCREMENT,
  username             VARCHAR(64)  NOT NULL,                 
  password_hash        VARCHAR(255) NOT NULL,                 
  display_name         VARCHAR(128) NOT NULL DEFAULT '',      
  feishu_member_id     VARCHAR(64)  NOT NULL DEFAULT '',      
  role                 VARCHAR(32)  NOT NULL DEFAULT 'member',
  team_name            VARCHAR(64)  NOT NULL DEFAULT '',      
  is_active            TINYINT(1)   NOT NULL DEFAULT 1,       
  is_superadmin        TINYINT(1)   NOT NULL DEFAULT 0,       
  token_version        INT UNSIGNED NOT NULL DEFAULT 1,       
  must_change_password TINYINT(1)   NOT NULL DEFAULT 0,       
  remark               VARCHAR(255) NOT NULL DEFAULT '',      
  created_at           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_username (username),
  KEY idx_member (feishu_member_id),
  KEY idx_role (role),
  KEY idx_team (team_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='应用登录用户（DIM）';

-- source: sql/022_app_auth_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS dim_app_user_permission (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    INT UNSIGNED NOT NULL,
  perm_key   VARCHAR(64)  NOT NULL,
  granted_by VARCHAR(64)  NOT NULL DEFAULT '',
  granted_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  remark     VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_perm (user_id, perm_key),
  KEY idx_perm (perm_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户操作权限映射（DIM）';

-- source: sql/022_app_auth_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_app_audit_log (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  at          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  user_id     INT UNSIGNED NOT NULL DEFAULT 0,
  username    VARCHAR(64)  NOT NULL DEFAULT '',
  action      VARCHAR(128) NOT NULL,                          
  target      VARCHAR(255) NOT NULL DEFAULT '',
  detail_json JSON         NULL,
  ip          VARCHAR(64)  NOT NULL DEFAULT '',
  ua          VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (id),
  KEY idx_user_at (user_id, at),
  KEY idx_action_at (action, at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='应用操作审计日志';

-- source: sql/023_app_user_role.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_app_user_role` (
  `id`         BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id`    BIGINT       NOT NULL COMMENT '关联 dim_app_user.id',
  `role_key`   VARCHAR(32)  NOT NULL COMMENT '角色: 超管/人事/财务/中台/运营主管/运营组员',
  `granted_by` VARCHAR(128)          COMMENT '授权人(登录名)',
  `granted_at` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '授权时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_role` (`user_id`, `role_key`),
  KEY `idx_role` (`role_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM: 账号-角色 多对多（一人多角色）';

-- source: sql/027_event_wfs_fee_missing_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_wfs_fee_missing_alert (
  id                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform              VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id              VARCHAR(64)  NOT NULL,
  store_name            VARCHAR(128) NOT NULL DEFAULT '' COMMENT '快照店铺名，展示用',
  item_id               VARCHAR(64)  NOT NULL,
  msku                  VARCHAR(128) NOT NULL,
  product_name          VARCHAR(255) NOT NULL DEFAULT '' COMMENT '快照产品名，展示用',
  cycle_start_date      DATE         NOT NULL COMMENT '本轮首次提醒日期=轮次锚点；补费/归档退出后再缺=新行',
  first_notified_at     DATETIME     NULL COMMENT '首次提醒发送时间',
  second_notified_at    DATETIME     NULL COMMENT '二次提醒发送时间；非空即已触发扣分',
  deduction_points      INT          NOT NULL DEFAULT 0 COMMENT '本轮扣分，二提时写5；首提期保持0',
  owner_name            VARCHAR(64)  NULL COMMENT '扣分承担人=落台账时该产品负责人(dim_product.owner)',
  deducted_at           DATETIME     NULL COMMENT '扣分落台账时间；非空即已落 biz_perf_deduction',
  announced_at          DATETIME     NULL COMMENT '扣分随日报公布时间',
  supervisor_synced_at  DATETIME     NULL COMMENT '扣分同步黄少如时间',
  status                VARCHAR(20)  NOT NULL DEFAULT 'open'
    COMMENT 'open=跟踪中(缺费) closed=已补费/结案 void=作废(归档/停用退出清单)',
  remark                VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统任务不得覆盖',
  created_at            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_wfs_cycle (platform, store_id, item_id, msku(64), cycle_start_date),
  KEY idx_wfs_status (status),
  KEY idx_wfs_owner (owner_name),
  KEY idx_wfs_item (item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='缺WFS配送费产品提醒轮次/扣分状态机（EVENT层，唯一写入方=unmatchedOwnerNotify）';

-- source: sql/028_event_gpt_link_missing_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_gpt_kw_missing_alert (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform VARCHAR(20) NOT NULL DEFAULT 'walmart',
  store_id VARCHAR(64) NOT NULL,
  store_name VARCHAR(128) NOT NULL DEFAULT '',
  item_id VARCHAR(64) NOT NULL,
  msku VARCHAR(128) NOT NULL,
  product_name VARCHAR(255) NOT NULL DEFAULT '',
  cycle_start_date DATE NOT NULL,
  first_notified_at DATETIME NULL,
  second_notified_at DATETIME NULL,
  deduction_points INT NOT NULL DEFAULT 0,
  owner_name VARCHAR(64) NULL COMMENT '扣分承担人=落台账时负责人',
  deducted_at DATETIME NULL,
  announced_at DATETIME NULL,
  supervisor_synced_at DATETIME NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'open' COMMENT 'open=缺链接 closed=已补链接/结案 void=作废',
  remark VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统不覆盖',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_kw_cycle (platform, store_id, item_id, msku(64), cycle_start_date),
  KEY idx_kw_status (status), KEY idx_kw_owner (owner_name), KEY idx_kw_item (item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='缺 GPT关键词分析链接 提醒轮次/扣分状态机（EVENT层，唯一写入方=unmatchedOwnerNotify）';

-- source: sql/028_event_gpt_link_missing_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_gpt_ads_missing_alert (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform VARCHAR(20) NOT NULL DEFAULT 'walmart',
  store_id VARCHAR(64) NOT NULL,
  store_name VARCHAR(128) NOT NULL DEFAULT '',
  item_id VARCHAR(64) NOT NULL,
  msku VARCHAR(128) NOT NULL,
  product_name VARCHAR(255) NOT NULL DEFAULT '',
  cycle_start_date DATE NOT NULL,
  first_notified_at DATETIME NULL,
  second_notified_at DATETIME NULL,
  deduction_points INT NOT NULL DEFAULT 0,
  owner_name VARCHAR(64) NULL COMMENT '扣分承担人=落台账时负责人',
  deducted_at DATETIME NULL,
  announced_at DATETIME NULL,
  supervisor_synced_at DATETIME NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'open' COMMENT 'open=缺链接 closed=已补链接/退出清单 void=作废',
  remark VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统不覆盖',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_ads_cycle (platform, store_id, item_id, msku(64), cycle_start_date),
  KEY idx_ads_status (status), KEY idx_ads_owner (owner_name), KEY idx_ads_item (item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='缺 GPT广告分析链接(WFS连续14天有库存) 提醒轮次/扣分状态机（EVENT层，唯一写入方=unmatchedOwnerNotify）';

-- source: sql/029_event_monthly_plan_unfilled.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_monthly_plan_unfilled (
  id             bigint unsigned NOT NULL AUTO_INCREMENT,
  plan_month     char(7)      COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规划月 YYYY-MM（=被扣的填报月）',
  deduction_date date         NOT NULL COMMENT '扣分日（被判未填的当天，中国时区）',
  platform       varchar(20)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart',
  owner_name     varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '负责人花名（扣分归属，与花名册一致）',
  unfilled_count int          NOT NULL DEFAULT 0 COMMENT '当日该负责人未完成品数（审计用；扣分固定5/人/天，与品数无关）',
  points         int          NOT NULL DEFAULT 5 COMMENT '当日扣分（固定5/人/天）',
  created_at     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_mpu_daily (deduction_date, platform, owner_name),
  KEY idx_mpu_month (plan_month),
  KEY idx_mpu_owner (owner_name, deduction_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='月度规划每日未填事件源（每负责人每天固定5分幂等去重；镜像入 biz_perf_deduction biz_type=monthly_plan_unfilled）';

-- source: sql/031_attendance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS raw_feishu_attendance (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  api_type    VARCHAR(32)  NOT NULL COMMENT 'user_tasks/user_flows/user_approvals',
  date_from   INT          NOT NULL COMMENT '窗口起(yyyymmdd 或 unix秒)',
  date_to     INT          NOT NULL COMMENT '窗口止',
  user_count  INT          NOT NULL DEFAULT 0,
  payload_json JSON        NOT NULL COMMENT '接口原样返回',
  raw_hash    VARCHAR(64)  NOT NULL COMMENT '去重哈希',
  pulled_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_hash (raw_hash),
  KEY idx_api_date (api_type, date_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='飞书考勤原始响应留存(RAW)';

-- source: sql/031_attendance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_attendance_daily (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  stat_date     DATE         NOT NULL COMMENT '考勤日',
  open_id       VARCHAR(64)  NOT NULL DEFAULT '',
  user_id       VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '飞书user_id(employee_id)',
  name          VARCHAR(128) NOT NULL DEFAULT '',
  group_id      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '考勤组',
  shift_id      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '班次',
  is_scheduled  TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '当天是否排班(大小周由飞书排班定)',
  check_in_time  DATETIME    NULL COMMENT '实际上班打卡',
  check_out_time DATETIME    NULL COMMENT '实际下班打卡(排班下班那次)',
  last_punch_time DATETIME   NULL COMMENT '当天最后一次打卡(含夜间加班)',
  check_in_result  VARCHAR(24) NOT NULL DEFAULT '' COMMENT 'Normal/Late/SeriousLate/Early/Lack',
  check_out_result VARCHAR(24) NOT NULL DEFAULT '',
  late_minutes  INT          NOT NULL DEFAULT 0,
  early_minutes INT          NOT NULL DEFAULT 0,
  overtime_minutes INT       NOT NULL DEFAULT 0 COMMENT '打卡超时=末次打卡-排班下班(无审批加班,纯打卡口径)',
  leave_type    VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '事假/病假/年假等(i18n_names.ch)',
  leave_hours   DECIMAL(6,2) NOT NULL DEFAULT 0,
  out_hours     DECIMAL(6,2) NOT NULL DEFAULT 0 COMMENT '外出时长',
  day_status    VARCHAR(16)  NOT NULL DEFAULT '' COMMENT '正常/迟到/早退/缺卡/旷工/请假/休息',
  remark        VARCHAR(255) NOT NULL DEFAULT '',
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_day_user (stat_date, open_id),
  KEY idx_month (stat_date),
  KEY idx_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='每人每天考勤(FACT,派生)';

-- source: sql/034_event_attendance_lack_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_attendance_lack_alert (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  stat_date    DATE         NOT NULL COMMENT '缺卡日',
  open_id      VARCHAR(64)  NOT NULL,
  user_id      VARCHAR(64)  NOT NULL DEFAULT '',
  name         VARCHAR(128) NOT NULL DEFAULT '',
  lack_type    VARCHAR(16)  NOT NULL DEFAULT '' COMMENT '上班/下班/双缺',
  ack_status   VARCHAR(16)  NOT NULL DEFAULT 'pending' COMMENT 'pending/confirmed/expired',
  push_at      DATETIME     NULL COMMENT '首次推送时刻(24/12h起算)',
  resend_at    DATETIME     NULL COMMENT '12h重发时刻',
  confirmed_at DATETIME     NULL,
  locked_at    DATETIME     NULL COMMENT '24h锁定(逾期)时刻',
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_day_user (stat_date, open_id),
  KEY idx_status (ack_status),
  KEY idx_date (stat_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='考勤缺卡通报事件(EVENT)';

-- source: sql/039_event_archived_restock_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_archived_restock_alert (
  id               bigint unsigned NOT NULL AUTO_INCREMENT,
  platform         varchar(20)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart',
  store_id         varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '店铺ID',
  item_id          varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Walmart ItemID',
  mskus            varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MSKU聚合串(展示用)',
  owner_name       varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '提醒时负责人',
  wfs_qty          int          NOT NULL DEFAULT 0 COMMENT '最近一次提醒时WFS库存',
  first_alert_date date         DEFAULT NULL COMMENT '首次提醒日',
  last_alert_date  date         DEFAULT NULL COMMENT '最近提醒日',
  decision         varchar(16)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '空=未处理 / restore=恢复在售 / keep=继续归档(不再提醒)',
  decided_by       varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '卡片操作人',
  decided_at       datetime     DEFAULT NULL,
  remark           varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '人工备注,系统不覆盖',
  created_at       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_ar_item (platform, store_id, item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='归档产品到货提醒事件(卡片按钮:恢复在售/继续归档) 2026-08-05';

-- source: sql/040_event_sentinel_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_sentinel_alert (
  id             bigint unsigned NOT NULL AUTO_INCREMENT,
  check_key      varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sales_family_eq/cxec21_rows/inventory_snapshot/msku_blank/channel_presence',
  target_date    date         NOT NULL COMMENT '被检查的数据日期',
  status         varchar(16)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open' COMMENT 'open=待处理 manual=转人工 resolved=已闭环',
  detail         varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '最近一次实测(期望vs实际)',
  attempt_count  int          NOT NULL DEFAULT 0 COMMENT '自动修复已执行次数(满2转人工)',
  remind_count   int          NOT NULL DEFAULT 0 COMMENT '已提醒次数',
  first_alert_at datetime     DEFAULT NULL,
  last_remind_at datetime     DEFAULT NULL,
  resolved_at    datetime     DEFAULT NULL,
  resolved_by    varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'sentinel_auto/recheck_pass/卡片操作人',
  remark         varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '人工备注,系统不覆盖',
  created_at     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sentinel (check_key, target_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='P7数据完整性哨兵事件(报警/确认/执行/复查留痕) 2026-08-10';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_settlement_msku_monthly` (
  `id`                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`          VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`          VARCHAR(64)  NOT NULL,
  `store_name`        VARCHAR(128) NOT NULL DEFAULT '',
  `msku`              VARCHAR(128) NOT NULL,
  `item_id`           VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '经dim_product映射，可空待回填',
  `settlement_month`  CHAR(7)      NOT NULL COMMENT '结算月 yyyy-MM（接口settlementDate为月粒度）',
  `currency_code`     VARCHAR(8)   NOT NULL DEFAULT 'USD',
  
  `sales_amount`      DECIMAL(18,4) NOT NULL DEFAULT 0,
  `sales_num`         INT NOT NULL DEFAULT 0,
  `promotion_amount`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'walmartPromoCode等促销合计(负)',
  `refund_amount`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '退款相关合计(负)',
  `tax_net_amount`    DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '税费净额(代收代缴通常≈0)',
  
  `commission_amount` DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'productCommission等佣金',
  `wfs_shipment_fee`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'WFS配送费',
  `wfs_inbound_fee`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'wfsWarehousFee入仓费',
  `wfs_prep_fee`      DECIMAL(18,4) NOT NULL DEFAULT 0,
  `other_platform_fee` DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '其余平台费净额',
  
  `purchase_amount`   DECIMAL(18,4) NOT NULL DEFAULT 0,
  `transportation_amount` DECIMAL(18,4) NOT NULL DEFAULT 0,
  `extra_json`        JSON NULL COMMENT '该msku该月list原始行全量留存',
  `amount_hash`       CHAR(32) NOT NULL DEFAULT '' COMMENT '金额指纹，变化=账期刷新+复核打回',
  `last_synced_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '账期更新时间(前端展示)',
  `source_raw_id`     BIGINT UNSIGNED NULL,
  `created_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_settle_month` (`platform`, `store_id`, `msku`(64), `settlement_month`),
  KEY `idx_settle_item` (`store_id`, `item_id`, `settlement_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·结算收入月度事实(USD原币,滚动3月每日重拉upsert)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_walmart_storage_csv` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `task_id`       VARCHAR(64)  NOT NULL COMMENT '导入批次 WMSTOR-yyyymmdd-nnnn',
  `store_id`      VARCHAR(64)  NOT NULL,
  `operator`      VARCHAR(64)  NOT NULL DEFAULT '',
  `report_start`  DATE NOT NULL,
  `report_end`    DATE NOT NULL,
  `row_no`        INT NOT NULL,
  `row_json`      JSON NOT NULL COMMENT 'CSV原始行',
  `raw_hash`      CHAR(32) NOT NULL,
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_storage_raw` (`task_id`, `row_no`),
  KEY `idx_storage_raw_store` (`store_id`, `report_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·沃尔玛仓储报告CSV原始留痕(只增)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_wfs_storage_fee` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL,
  `sku`             VARCHAR(128) NOT NULL COMMENT '报告SKU列=MSKU',
  `gtin`            VARCHAR(32)  NOT NULL DEFAULT '',
  `item_id`         VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '经dim_product映射回填',
  `report_start`    DATE NOT NULL,
  `report_end`      DATE NOT NULL,
  `days_in_period`  INT NOT NULL DEFAULT 0,
  `avg_units_standard` DECIMAL(12,3) NOT NULL DEFAULT 0,
  `avg_units_longterm` DECIMAL(12,3) NOT NULL DEFAULT 0,
  `final_storage_fee`  DECIMAL(18,5) NOT NULL DEFAULT 0,
  `original_amount`    DECIMAL(18,5) NOT NULL DEFAULT 0,
  `discount_savings`   DECIMAL(18,5) NOT NULL DEFAULT 0,
  `source_task_id`  VARCHAR(64) NOT NULL DEFAULT '',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_storage_fee` (`platform`, `store_id`, `sku`(64), `report_start`, `report_end`),
  KEY `idx_storage_fee_item` (`store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·WFS仓储费SKU级事实(报告期粒度,重复导入幂等覆盖)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_purchase_cash` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn`        VARCHAR(64)  NOT NULL,
  `order_time`      DATE NOT NULL COMMENT '现金支出记账日=下单日',
  `status_text`     VARCHAR(32)  NOT NULL DEFAULT '',
  `amount_total`    DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '采购单总额(每周复核窗口内可被刷新)',
  `currency_code`   VARCHAR(8)   NOT NULL DEFAULT 'CNY',
  `review_close_at` DATE NULL COMMENT '复核收口日=下单次月末,过期不再刷新',
  `amount_hash`     CHAR(32) NOT NULL DEFAULT '',
  `source_raw_id`   BIGINT UNSIGNED NULL,
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pcash_order` (`order_sn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·采购单现金支出线(头表;明细金额进 fact_purchase_cash_item)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_purchase_cash_item` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_sn`      VARCHAR(64)  NOT NULL,
  `sku`           VARCHAR(128) NOT NULL DEFAULT '',
  `msku`          VARCHAR(128) NOT NULL DEFAULT '',
  `quantity`      INT NOT NULL DEFAULT 0,
  `unit_price`    DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'item_list.price真实单价(探针1验证)',
  `amount`        DECIMAL(18,4) NOT NULL DEFAULT 0,
  `source_raw_id` BIGINT UNSIGNED NULL,
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pcash_item` (`order_sn`, `sku`(64), `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·采购单明细金额(真实单价,成本归集输入)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_item_landed_cost` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '可空=跨店共享SKU成本',
  `sku`             VARCHAR(128) NOT NULL,
  `msku`            VARCHAR(128) NOT NULL DEFAULT '',
  `item_id`         VARCHAR(64)  NOT NULL DEFAULT '',
  `cost_month`      CHAR(7)      NOT NULL COMMENT '归集月',
  `purchase_unit_cost`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '采购单价(采购单归集)',
  `firstmile_unit_cost` DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '头程单价(发货单归集)',
  `landed_unit_cost`    DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '=采购+头程',
  `cost_source`     VARCHAR(32)  NOT NULL DEFAULT 'collected' COMMENT 'collected=自算归集 / batch_api=批次成本接口回补(历史缺失)',
  `currency_code`   VARCHAR(8)   NOT NULL DEFAULT 'CNY',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_landed_cost` (`platform`, `store_id`, `sku`(64), `cost_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·真实入库成本单价(复核对象;历史缺失cost_source=batch_api)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_inbound_freight_alloc` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `cargo_code`     VARCHAR(128) NOT NULL COMMENT '沃尔玛账单ShipmentID=货件单号(探针15实锤,WFA/WFB通配)',
  `shipment_id`    VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '领星货件id',
  `settlement_month` CHAR(7)    NOT NULL COMMENT '费用归属结算月',
  `msku`           VARCHAR(128) NOT NULL,
  `item_id`        VARCHAR(64)  NOT NULL DEFAULT '',
  `declare_num`    INT NOT NULL DEFAULT 0,
  `freight_total`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '该货件真实运费(账单)',
  `alloc_amount`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '=freight_total×declare_num占比',
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_freight_alloc` (`platform`, `store_id`, `cargo_code`(64), `msku`(64)),
  KEY `idx_freight_month` (`store_id`, `settlement_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·入库运输费货件→品分摊结果(审计留存)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_finance_fixed_cost` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `cost_month`    CHAR(7)      NOT NULL,
  `level`         VARCHAR(16)  NOT NULL COMMENT 'company=公司级 / store=店铺级',
  `store_id`      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT 'level=store时必填',
  `category`      VARCHAR(64)  NOT NULL COMMENT '人工/场地/财务成本/公司日常/其他',
  `amount`        DECIMAL(18,4) NOT NULL,
  `currency_code` VARCHAR(8)   NOT NULL DEFAULT 'CNY',
  `remark`        VARCHAR(500) NOT NULL DEFAULT '' COMMENT '人工备注列',
  `created_by`    VARCHAR(64)  NOT NULL COMMENT '录入人(超管/财务)',
  `updated_by`    VARCHAR(64)  NOT NULL DEFAULT '',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fixed_cost` (`cost_month`, `level`, `store_id`, `category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·固定开支月度人工录入(公司级全额归Walmart;销售额占比分摊;零销量品不参与)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_finance_review` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `item_id`        VARCHAR(64)  NOT NULL,
  `period_month`   CHAR(7)      NOT NULL COMMENT '账单周期(月)',
  `review_status`  VARCHAR(16)  NOT NULL DEFAULT 'pending' COMMENT 'pending=待复核 / reviewed=已复核(数据刷新自动打回pending)',
  `reviewed_by`    VARCHAR(64)  NOT NULL DEFAULT '',
  `reviewed_at`    DATETIME NULL,
  `data_hash`      CHAR(32) NOT NULL DEFAULT '' COMMENT '复核时数据指纹,变化即打回',
  `remark`         VARCHAR(500) NOT NULL DEFAULT '' COMMENT '人工备注列',
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fin_review` (`platform`, `store_id`, `item_id`, `period_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·人工复核标记(对象=销售利润表产品成本+头程;只标记不改数)';

-- source: sql/041_ai_finance_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_finance_sentinel_alert` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `check_time`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `equation`       VARCHAR(32)  NOT NULL COMMENT 'fixed_alloc/ads/storage/freight/revenue 五等式',
  `store_id`       VARCHAR(64)  NOT NULL DEFAULT '',
  `period_month`   CHAR(7)      NOT NULL,
  `expected_total` DECIMAL(18,4) NOT NULL COMMENT '账单/录入原额',
  `actual_total`   DECIMAL(18,4) NOT NULL COMMENT '归属/分摊加总',
  `diff_amount`    DECIMAL(18,4) NOT NULL,
  `diff_pct`       DECIMAL(10,4) NOT NULL,
  `threshold_hit`  TINYINT NOT NULL DEFAULT 0 COMMENT '1=超阈值(>1%或>$50取大者)已报警',
  `detail_json`    JSON NULL,
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sentinel_eq` (`equation`, `period_month`),
  KEY `idx_sentinel_hit` (`threshold_hit`, `check_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·守恒哨兵校验事件(只增;超阈值飞书报警超管+财务)';

