-- source: sql/042_ai_finance_reconciliation.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_walmart_reconciliation_csv` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `task_id`       VARCHAR(64)  NOT NULL COMMENT '导入批次 WMRECON-yyyymmdd-nnnn',
  `store_id`      VARCHAR(64)  NOT NULL,
  `operator`      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '导入人(超管/财务)',
  `period_start`  DATE NOT NULL,
  `period_end`    DATE NOT NULL,
  `row_no`        INT NOT NULL,
  `row_json`      JSON NOT NULL COMMENT 'CSV原始行(含Transaction Key/Type/Amount Type等全字段)',
  `raw_hash`      CHAR(32) NOT NULL,
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recon_raw` (`task_id`, `row_no`),
  KEY `idx_recon_raw_store` (`store_id`, `period_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·沃尔玛对账单CSV原始留痕(只增)';

-- source: sql/042_ai_finance_reconciliation.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_reconciliation_period` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `period_start`   DATE NOT NULL COMMENT '账单周期起(每两周一期,起止不固定)',
  `period_end`     DATE NOT NULL,
  `payment_date`   DATE NULL COMMENT '回款日期(可延迟)',
  `total_payable`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '账单Total Payable(守恒基准)',
  `currency_code`  VARCHAR(8)   NOT NULL DEFAULT 'USD',
  `import_task_id` VARCHAR(64)  NOT NULL DEFAULT '',
  `period_status`  VARCHAR(16)  NOT NULL DEFAULT 'imported' COMMENT 'imported=已导入 / confirmed=人工确认可核算 / closed=已核算收口',
  `confirmed_by`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '人工确认人(超管/财务)',
  `confirmed_at`   DATETIME NULL,
  `remark`         VARCHAR(500) NOT NULL DEFAULT '' COMMENT '人工备注列',
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recon_period` (`platform`, `store_id`, `period_start`, `period_end`),
  KEY `idx_recon_period_status` (`period_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·账单周期登记(核算周期由人工选择确认;confirmed/remark为人工列)';

-- source: sql/042_ai_finance_reconciliation.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_reconciliation_item` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `period_start`   DATE NOT NULL,
  `period_end`     DATE NOT NULL,
  `item_id`        VARCHAR(64)  NOT NULL DEFAULT '' COMMENT 'Partner Item Id;店铺级类目行为空串',
  `gtin`           VARCHAR(32)  NOT NULL DEFAULT '',
  `msku`           VARCHAR(128) NOT NULL DEFAULT '' COMMENT '经dim_product/GTIN映射回填',
  `fee_category`   VARCHAR(64)  NOT NULL COMMENT '分类键:sale/shipping/tax_net/commission/refund_keepit/refund_return/wfs_fulfillment/ad_platform/sem/storage/inbound_transport/removal/lost_inventory/found_inventory/return_processing/damage/prep/review_accelerator/discount_adj/other(按Transaction Type+Description映射,映射表入代码常量并文档化)',
  `amount`         DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '该品该周期该类目净额(账单符号原样:收入正/扣费负)',
  `txn_count`      INT NOT NULL DEFAULT 0,
  `currency_code`  VARCHAR(8)   NOT NULL DEFAULT 'USD',
  `source_task_id` VARCHAR(64)  NOT NULL DEFAULT '',
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_recon_item` (`platform`, `store_id`, `period_start`, `period_end`, `item_id`, `fee_category`),
  KEY `idx_recon_item_item` (`store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·对账单周期×品×类目净额(核算主数据;Σamount=周期total_payable为哨兵守恒)';

-- source: sql/042_ai_finance_reconciliation.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_finance_exchange_rate` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `rate_month`    CHAR(7)      NOT NULL COMMENT 'yyyy-MM',
  `currency_pair` VARCHAR(16)  NOT NULL DEFAULT 'USD/CNY',
  `rate`          DECIMAL(12,6) NOT NULL COMMENT '1美元兑人民币',
  `remark`        VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注列',
  `created_by`    VARCHAR(64)  NOT NULL,
  `updated_by`    VARCHAR(64)  NOT NULL DEFAULT '',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fx_month` (`rate_month`, `currency_pair`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·月度汇率人工录入(财务工具;成本CNY↔账单USD折算)';

-- source: sql/042_event_wfs_fee_case.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_wfs_fee_case (
  id               bigint unsigned NOT NULL AUTO_INCREMENT,
  platform         varchar(20)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart',
  store_id         varchar(64)   COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '店铺ID',
  store_name       varchar(255)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  item_id          varchar(64)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '展示用ItemID',
  msku             varchar(128)  COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MSKU(判定粒度)',
  owner_name       varchar(64)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '立案时负责人',
  manual_fee       decimal(10,4) NOT NULL DEFAULT 0 COMMENT '人工WFS配送费(cost_config.delivery_fee)',
  actual_fee       decimal(10,4) NOT NULL DEFAULT 0 COMMENT '实收单件费率(wfs_fee_auto.fee,结算众数)',
  total_units      int           NOT NULL DEFAULT 0 COMMENT '全历史累计销量(fact_sales_daily)',
  est_recover      decimal(12,2) NOT NULL DEFAULT 0 COMMENT '预估追回=(actual-manual)*total_units',
  status           varchar(16)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'waiting' COMMENT 'waiting待运营确认/following跟进中/approving待林翔审批/done已追回/closed已关闭不追',
  case_nos         varchar(255)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '人工:Case号,逗号分隔可多个,转following必填',
  reason           varchar(500)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '人工:不跟进/放弃理由(送审必填)',
  follow_log       mediumtext    COLLATE utf8mb4_unicode_ci COMMENT '人工:跟进日志(可编辑文本,系统不覆盖)',
  log_updated_at   datetime      DEFAULT NULL COMMENT '日志最后保存时间(周检查扣绩效依据)',
  claim_amount     decimal(12,2) DEFAULT NULL COMMENT '人工:索赔金额(完成时填)',
  recovered_amount decimal(12,2) DEFAULT NULL COMMENT '人工:实际追回金额(完成时填)',
  decided_by       varchar(64)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '运营操作人',
  approved_by      varchar(64)   COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '审批人',
  approved_at      datetime      DEFAULT NULL,
  done_at          datetime      DEFAULT NULL,
  first_alert_at   datetime      DEFAULT NULL COMMENT '首次发卡时间',
  remark           varchar(255)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '人工备注,系统不覆盖',
  created_at       datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '立案时间(默认排序键)',
  updated_at       datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_wfs_case (platform, store_id, msku),
  KEY idx_status_created (status, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='WFS费用异常跟进(智能PMC,实收>人工立案,林翔审批不追,周日志扣绩效) 2026-08-11';

-- source: sql/044_ai_finance_sem_and_credits.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_walmart_sem_csv` (
  `id`          BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id`     VARCHAR(40) NOT NULL COMMENT '导入任务ID（WMSEM-YYYYMMDD-XXXX）',
  `row_index`   INT NOT NULL COMMENT 'CSV行号（0起）',
  `csv_type`    VARCHAR(20) NOT NULL COMMENT 'CSV类型: sem_daily=每日报表 / sem_billing=账单历史',
  `row_json`    JSON NOT NULL COMMENT '原始行JSON',
  `report_date` VARCHAR(20) DEFAULT NULL COMMENT '行内日期（sem_daily=Date列 / sem_billing=Billing From）',
  `store_id`    VARCHAR(64) NOT NULL DEFAULT '' COMMENT '店铺ID',
  `store_name`  VARCHAR(255) DEFAULT NULL COMMENT '店铺名称',
  `operator`    VARCHAR(128) DEFAULT NULL COMMENT '导入操作人',
  `raw_hash`    VARCHAR(64) NOT NULL COMMENT '行内容hash',
  `created_at`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sem_raw` (`task_id`, `row_index`),
  KEY `idx_sem_raw_store_date` (`store_id`, `report_date`),
  KEY `idx_sem_raw_type` (`csv_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW层: 沃尔玛SEM广告CSV原始行留存（每日报表+账单历史）';

-- source: sql/044_ai_finance_sem_and_credits.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_sem_billing_daily` (
  `id`              BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`        VARCHAR(32) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`        VARCHAR(64) NOT NULL COMMENT '店铺ID',
  `store_name`      VARCHAR(255) DEFAULT NULL COMMENT '店铺名称（展示用）',
  `invoice_id`      VARCHAR(40) NOT NULL COMMENT 'SEM发票ID',
  `invoice_date`    DATE DEFAULT NULL COMMENT '发票日期',
  `billing_from`    DATE NOT NULL COMMENT '账单开始日（=SEM花费日）',
  `billing_to`      DATE DEFAULT NULL COMMENT '账单结束日（跨天发票才不同于from）',
  `charge_type`     VARCHAR(20) NOT NULL DEFAULT 'DEBIT' COMMENT 'DEBIT=扣费 / AD_CREDIT=返还',
  `invoice_total`   DECIMAL(18,4) DEFAULT NULL COMMENT '发票总额（Total Amount）',
  `campaign_id`     VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'Campaign ID（返还行=NA）',
  `campaign_name`   VARCHAR(255) DEFAULT NULL COMMENT 'Campaign/Reimbursement Name',
  `line_amount`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '行金额（Line Item Amount）',
  `currency_code`   VARCHAR(8) NOT NULL DEFAULT 'USD' COMMENT '币种',
  `pay_status`      VARCHAR(20) DEFAULT NULL COMMENT 'Status（SUCCESS等）',
  `payment_mode`    VARCHAR(20) DEFAULT NULL COMMENT 'Payment Mode（SETTLEMENT等）',
  `additional_info` VARCHAR(255) DEFAULT NULL COMMENT 'Additional Info',
  `item_id`         VARCHAR(64) NOT NULL DEFAULT '' COMMENT '归属ItemID（campaign名解析；解析失败留空）',
  `source_task_id`  VARCHAR(40) DEFAULT NULL COMMENT '导入任务ID',
  `remark`          VARCHAR(500) DEFAULT NULL COMMENT '人工备注（系统不覆盖）',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sem_billing` (`store_id`, `invoice_id`, `campaign_id`, `charge_type`),
  KEY `idx_sem_billing_from` (`store_id`, `billing_from`),
  KEY `idx_sem_billing_item` (`item_id`),
  KEY `idx_sem_billing_type` (`charge_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: SEM广告账单历史（发票行级，含AD_CREDIT返还；修复/对账源）';

-- source: sql/044_ai_finance_sem_and_credits.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ad_credit_detail` (
  `id`               BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`         VARCHAR(32) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`         VARCHAR(64) NOT NULL COMMENT '店铺ID',
  `posted_date`      DATE NOT NULL COMMENT '入账日期',
  `period_start`     DATE DEFAULT NULL COMMENT '所属账单周期开始',
  `period_end`       DATE DEFAULT NULL COMMENT '所属账单周期结束',
  `fee_category`     VARCHAR(64) NOT NULL COMMENT '类目: ad_credit/wfs_refund/lost_inventory/found_inventory/sem_credit',
  `transaction_type` VARCHAR(64) DEFAULT NULL COMMENT '原transactionType',
  `transaction_desc` VARCHAR(255) DEFAULT NULL COMMENT '原transactionDescription',
  `amount`           DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '金额（正=返还入账，负=冲回）',
  `currency_code`    VARCHAR(8) NOT NULL DEFAULT 'USD' COMMENT '币种',
  `campaign_id`      VARCHAR(64) NOT NULL DEFAULT '' COMMENT '关联CampaignID（有则存）',
  `source_ref`       VARCHAR(128) NOT NULL COMMENT '来源行唯一标识（statement=transactionKey / SEM=发票号拼接）',
  `source_system`    VARCHAR(64) NOT NULL DEFAULT 'lingxing_api' COMMENT '来源系统',
  `source_task_id`   VARCHAR(64) DEFAULT NULL COMMENT '来源任务',
  `remark`           VARCHAR(500) DEFAULT NULL COMMENT '人工备注（系统不覆盖）',
  `created_at`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_credit_detail` (`platform`, `store_id`, `source_ref`),
  KEY `idx_credit_posted` (`store_id`, `posted_date`),
  KEY `idx_credit_category` (`fee_category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 返还/退款/赔付 行级明细（AI财务·返还明细页面数据源；含自发现的other:*类型）';

-- source: sql/045_ai_finance_commission_saving.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_commission_saving` (
  `id`                BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`          VARCHAR(32) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`          VARCHAR(64) NOT NULL COMMENT '店铺ID',
  `period_start`      DATE NOT NULL COMMENT '账单周期开始',
  `period_end`        DATE NOT NULL COMMENT '账单周期结束',
  `msku`              VARCHAR(128) NOT NULL DEFAULT '' COMMENT 'MSKU（partnerItemId）',
  `item_id`           VARCHAR(64) NOT NULL DEFAULT '' COMMENT 'ItemID（dim_product唯一命中回填，可空）',
  `incentive_program` VARCHAR(128) NOT NULL DEFAULT '' COMMENT '激励计划（commissionIncentiveProgram，如New Seller Saving/PRO/Pro Listing）',
  `saving_amount`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '佣金节省Σ（Sale行commissionSaving，激励中心口径）',
  `txn_count`         INT NOT NULL DEFAULT 0 COMMENT '行数',
  `currency_code`     VARCHAR(8) NOT NULL DEFAULT 'USD' COMMENT '币种',
  `source_task_id`    VARCHAR(64) DEFAULT NULL COMMENT '来源任务',
  `remark`            VARCHAR(500) DEFAULT NULL COMMENT '人工备注（系统不覆盖）',
  `created_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_comm_saving` (`platform`, `store_id`, `period_start`, `period_end`, `msku`(64), `incentive_program`(64)),
  KEY `idx_comm_saving_store` (`store_id`, `period_start`),
  KEY `idx_comm_saving_item` (`item_id`),
  KEY `idx_comm_saving_program` (`incentive_program`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 佣金折扣聚合（店铺×账期×MSKU×激励计划；信息指标，不参与现金守恒）';

-- source: sql/046_sem_naming_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_sem_naming_alert` (
  `id`              BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`        VARCHAR(32) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`        VARCHAR(64) NOT NULL COMMENT '店铺ID',
  `store_name`      VARCHAR(255) DEFAULT NULL COMMENT '店铺名称',
  `campaign_id`     VARCHAR(64) NOT NULL COMMENT 'SEM Campaign ID',
  `campaign_name`   VARCHAR(255) DEFAULT NULL COMMENT 'Campaign名称（随导入刷新）',
  `owner_name`      VARCHAR(128) NOT NULL DEFAULT '' COMMENT '负责人（campaign名SKU前缀→dim_product唯一命中；空=无法归属）',
  `owner_open_id`   VARCHAR(64) NOT NULL DEFAULT '' COMMENT '负责人open_id（发送时回填，回调校验用）',
  `first_seen_date` DATE NOT NULL COMMENT '首次发现日',
  `last_seen_date`  DATE NOT NULL COMMENT '最近仍不合规的数据日',
  `status`          VARCHAR(16) NOT NULL DEFAULT 'open' COMMENT 'open=不合规 / resolved=改名归属成功',
  `resolved_at`     DATETIME DEFAULT NULL COMMENT '整改判定时间',
  `ack_status`      VARCHAR(16) NOT NULL DEFAULT 'pending' COMMENT 'pending=待确认 / confirmed=已确认',
  `confirmed_at`    DATETIME DEFAULT NULL COMMENT '确认时间',
  `confirmed_by`    VARCHAR(128) DEFAULT NULL COMMENT '确认人',
  `last_push_at`    DATETIME DEFAULT NULL COMMENT '最近一次推送时间（5h重发判据）',
  `push_count`      INT NOT NULL DEFAULT 0 COMMENT '累计推送次数',
  `remark`          VARCHAR(500) DEFAULT NULL COMMENT '人工备注（系统不覆盖）',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sem_naming` (`platform`, `store_id`, `campaign_id`),
  KEY `idx_sem_naming_status` (`status`, `ack_status`),
  KEY `idx_sem_naming_owner` (`owner_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='EVENT层: SEM命名不合规campaign台账（通报/确认/整改状态机）';

-- source: sql/046_sem_naming_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_sem_naming_deduction` (
  `id`           BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ded_date`     DATE NOT NULL COMMENT '扣分日',
  `owner_name`   VARCHAR(128) NOT NULL COMMENT '负责人',
  `alert_count`  INT NOT NULL DEFAULT 0 COMMENT '当日仍不合规campaign数',
  `points`       INT NOT NULL DEFAULT 5 COMMENT '扣分（每人每天固定5分，与月度规划同口径）',
  `campaign_ids` VARCHAR(1000) DEFAULT NULL COMMENT '涉及campaign_id清单（留档）',
  `notified_at`  DATETIME DEFAULT NULL COMMENT '本人私信通知时间',
  `created_at`   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sem_ded` (`ded_date`, `owner_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='EVENT层: SEM命名不合规每日扣分事件（镜像biz_perf_deduction）';

-- source: sql/047_walmart_refund_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS raw_walmart_return_order (
  id                 bigint unsigned NOT NULL AUTO_INCREMENT,
  return_order_id    varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '售后单号(平台RMA)',
  msku               varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  customer_order_id  varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  purchase_order_id  varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '平台订单号',
  store_id           varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL,
  return_type        varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'REFUND/REPLACEMENT/PREORDER',
  item_status        varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'INITIATED/DELIVERED/COMPLETED',
  refund_status      varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'REFUND_COMPLETED/NOT_REFUNDED等',
  return_order_date  datetime     DEFAULT NULL COMMENT '售后申请时间(归因日)',
  purchase_time      datetime     DEFAULT NULL COMMENT '原订单下单时间',
  quantity           int          NOT NULL DEFAULT 0,
  line_total_amount  decimal(12,2) NOT NULL DEFAULT 0 COMMENT '退款金额(含税)',
  return_reason      varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  return_description varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  row_json           json         NOT NULL COMMENT '接口原样(单头+该明细)',
  capture_batch      varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  created_at         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_return_item (return_order_id, msku),
  KEY idx_return_date (return_order_date),
  KEY idx_store_msku (store_id, msku)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Walmart售后订单RAW(领星returnOrder/list原样) 2026-08-14';

-- source: sql/047_walmart_refund_tables.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_refund_daily (
  id             bigint unsigned NOT NULL AUTO_INCREMENT,
  platform       varchar(20)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart',
  store_id       varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL,
  item_id        varchar(64)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '经dim_product(店铺+MSKU)映射,未映射为空',
  msku           varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  refund_date    date         NOT NULL COMMENT '售后申请日(归因日)',
  refund_orders  int          NOT NULL DEFAULT 0 COMMENT '退款单数',
  refund_qty     int          NOT NULL DEFAULT 0 COMMENT '退款件数',
  refund_amount  decimal(12,2) NOT NULL DEFAULT 0 COMMENT '退款金额(含税净额)',
  source_system  varchar(32)  COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart_return_api',
  created_at     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_refund (platform, store_id, msku, refund_date),
  KEY idx_refund_date (refund_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='退货日聚合FACT(店铺×MSKU×日,V2订单利润用) 2026-08-14';

-- source: sql/048_promo_discount_storage_daily.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_mp_order_discount` (
  `id`                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform_order_no` VARCHAR(64)  NOT NULL COMMENT '平台单号',
  `order_item_no`     VARCHAR(64)  NOT NULL COMMENT '订单明细单号(商品行唯一)',
  `global_order_no`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '领星系统单号',
  `store_id`          VARCHAR(64)  NOT NULL,
  `msku`              VARCHAR(128) NOT NULL,
  `purchase_time`     DATETIME     NULL COMMENT '订购时间(北京时区换算)',
  `purchase_date`     DATE         NULL COMMENT '归因日=订购日(北京时区)',
  `order_status`      INT          NOT NULL DEFAULT 0 COMMENT '领星系统订单状态,7=已取消/不发货(FACT排除)',
  `quantity`          INT          NOT NULL DEFAULT 0,
  `item_price_amount` DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '商品金额(折前)',
  `discount_amount`   DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '折扣额,接口原符号(负值=优惠)',
  `currency`          VARCHAR(8)   NOT NULL DEFAULT '' COMMENT 'amount_currency',
  `row_json`          JSON         NOT NULL COMMENT '{order:单头精简,item:商品行原样}',
  `capture_batch`     VARCHAR(32)  NOT NULL DEFAULT '',
  `created_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_discount_item` (`platform_order_no`, `order_item_no`),
  KEY `idx_discount_pdate` (`purchase_date`),
  KEY `idx_discount_store_msku` (`store_id`, `msku`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='订单利润V2·促销折扣RAW(订单列表接口,仅折扣行,幂等upsert)';

-- source: sql/048_promo_discount_storage_daily.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_promo_discount_daily` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
