  `source_system`   VARCHAR(32)  NOT NULL DEFAULT 'mp_order_api',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_promo` (`platform`, `store_id`, `msku`(64), `discount_date`),
  KEY `idx_promo_date` (`discount_date`),
  KEY `idx_promo_store_item` (`store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='订单利润V2·促销折扣FACT(窗口聚合重算,排除已取消status=7)';

-- source: sql/048_promo_discount_storage_daily.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_storage_fee_daily` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
