-- source: sql/056_shipping_first_let.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_shipping_order` (
  `id`                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`              VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `shipping_code`         VARCHAR(64)  NOT NULL COMMENT '发货单号 SP…',
  `shipping_status`       VARCHAR(32)  NOT NULL DEFAULT '',
  `head_fee_type`         VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '领星分摊方式，如「按计费重」',
  `warehouse_id`          VARCHAR(32)  NOT NULL DEFAULT '',
  `logistics_code`        VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '物流中心编码，如 LAX2T',
  `creator`               VARCHAR(64)  NOT NULL DEFAULT '',
  `gmt_create`            DATETIME NULL COMMENT '发货单创建时间',
  `delivery_time`         DATE NULL COMMENT '发货时间',
  `actual_delivery_time`  DATE NULL COMMENT '实际发货时间=头程现金记账日(需求方拍板)',
  `sail_time`             DATE NULL COMMENT '开船时间',
  `expected_arrival_time` DATE NULL COMMENT '预计到港',
  `arrival_time`          DATE NULL COMMENT '到货时间(预计值,会变)',
  `transportation_cost`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '整单真实头程运费Σ(shipping_logistics)',
  `other_cost`            DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '整单其他费用Σ',
  `currency_code`         VARCHAR(8)   NOT NULL DEFAULT 'CNY',
  `alloc_sum`             DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '按品分摊回加总Σ(单位头程×发货量)',
  `alloc_diff`            DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '=alloc_sum-transportation_cost，守恒哨兵用',
  `first_let_rows`        INT NOT NULL DEFAULT 0 COMMENT '头程分摊明细行数',
  `unmatched_rows`        INT NOT NULL DEFAULT 0 COMMENT '未能反查到货件/店铺的明细行数',
  `source_raw_id`         BIGINT UNSIGNED NULL,
  `created_at`            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_shipping_order` (`platform`, `shipping_code`),
  KEY `idx_shipping_actual` (`actual_delivery_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·平台仓发货单头(整单真实头程运费;现金记账日=actual_delivery_time)';

-- source: sql/056_shipping_first_let.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_shipping_first_let` (
  `id`                  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`            VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `shipping_code`       VARCHAR(64)  NOT NULL,
  `store_id`            VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '取自 shipping_goods 反查(发货单可跨店)',
  `cargo_code`          VARCHAR(128) NOT NULL DEFAULT '' COMMENT '货件号，串联 WFS货件/入库运输费',
  `msku`                VARCHAR(128) NOT NULL,
  `sku`                 VARCHAR(128) NOT NULL DEFAULT '',
  `gtin`                VARCHAR(32)  NOT NULL DEFAULT '',
  `item_id`             VARCHAR(64)  NOT NULL DEFAULT '' COMMENT 'dim_product 唯一命中才回填',
  `delivery_num`        INT NOT NULL DEFAULT 0 COMMENT '发货量',
  `value_source`        VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '取值来源，如「实际费用」',
  `purchase_price`      DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:采购单价',
  `outbound_price`      DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位出库费用 (API字段名 price)',
  `aux_stock_price`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位辅料费用',
  `per_tax`             DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位税费',
  `head_stock_price`    DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位出库头程',
  `per_first_let_cost`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位头程费用',
  `wfs_stock_price`     DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT 'UI:单位WFS入库成本(=以上各项之和)',
  `currency_code`       VARCHAR(8)   NOT NULL DEFAULT 'CNY',
  `match_status`        VARCHAR(16)  NOT NULL DEFAULT 'matched' COMMENT 'matched=唯一命中货件 / ambiguous=同msku同数量多货件(不猜) / unmatched=无命中',
  `actual_delivery_time` DATE NULL COMMENT '冗余自发货单头，按月归集用',
  `source_raw_id`       BIGINT UNSIGNED NULL,
  `created_at`          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_first_let` (`platform`, `shipping_code`, `msku`(64), `delivery_num`, `cargo_code`(64)),
  KEY `idx_first_let_store_sku` (`store_id`, `sku`(64), `actual_delivery_time`),
  KEY `idx_first_let_cargo` (`cargo_code`(64))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·发货单头程分摊明细(领星成品值,逐项留存;单价单位=CNY/件)';

-- source: sql/057_shipping_currency_and_freight_alert.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_shipping_freight_alert` (
  `id`                   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`             VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `shipping_code`        VARCHAR(64)  NOT NULL COMMENT '发货单号',
  `creator`              VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '发货单创建人(领星操作人)',
  `owner_name`           VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '补录责任人(需求方定：统一刘晶晶)',
  `shipping_status`      VARCHAR(32)  NOT NULL DEFAULT '',
  `delivery_time`        DATE NULL,
  `cash_date`            DATE NULL,
  `logistics_provider_id` VARCHAR(32) NOT NULL DEFAULT '',
  `logistics_channel_id`  VARCHAR(32) NOT NULL DEFAULT '',
  `logistics_code`       VARCHAR(32)  NOT NULL DEFAULT '',
  `freight_cny`          DECIMAL(18,4) NOT NULL DEFAULT 0,
  `freight_usd`          DECIMAL(18,4) NOT NULL DEFAULT 0,
  `other_cny`            DECIMAL(18,4) NOT NULL DEFAULT 0,
  `other_usd`            DECIMAL(18,4) NOT NULL DEFAULT 0,
  `store_names`          VARCHAR(500) NOT NULL DEFAULT '' COMMENT '涉及店铺(可跨店)',
  `cargo_codes`          VARCHAR(500) NOT NULL DEFAULT '' COMMENT '涉及货件号',
  `is_legacy`            TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1=起算日之前的历史遗留，只出清单不计绩效',
  `status`               VARCHAR(16)  NOT NULL DEFAULT 'open' COMMENT 'open=待补录 / resolved=已补录',
  `first_found_at`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_push_at`         DATETIME NULL,
  `push_count`           INT NOT NULL DEFAULT 0,
  `resolved_at`          DATETIME NULL,
  `penalty_points`       DECIMAL(10,2) NOT NULL DEFAULT 0 COMMENT '累计已扣分',
  `last_penalty_date`    DATE NULL COMMENT '最近一次扣分日，按天防重',
  `note`                 VARCHAR(500) NOT NULL DEFAULT '' COMMENT '人工备注列，同步永不覆盖',
  `created_at`           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_freight_alert` (`platform`, `shipping_code`),
  KEY `idx_freight_alert_status` (`status`, `is_legacy`),
  KEY `idx_freight_alert_owner` (`owner_name`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·发货单运费未录入通报台账(已发货且物流费=0;补录是关闭的唯一方式)';

-- source: sql/058_lingxing_fx_rate.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_lingxing_fx_rate` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `rate_month`     CHAR(7)      NOT NULL COMMENT '汇率年月 yyyy-MM（接口 data>>date）',
  `currency_code`  VARCHAR(8)   NOT NULL COMMENT '币种代码，如 USD/CNY',
  `currency_name`  VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '币种名',
  `icon`           VARCHAR(8)   NOT NULL DEFAULT '' COMMENT '币种符号',
  `rate_org`       DECIMAL(20,10) NOT NULL DEFAULT 0 COMMENT '官方汇率(中国银行)',
  `my_rate`        DECIMAL(20,10) NOT NULL DEFAULT 0 COMMENT '我的汇率(财务在领星录入;领星算成本优先用它)=主口径',
  `lx_update_time` DATETIME NULL COMMENT '领星侧更新时间',
  `source_raw_id`  BIGINT UNSIGNED NULL,
  `created_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lx_fx` (`rate_month`, `currency_code`),
  KEY `idx_lx_fx_code` (`currency_code`, `rate_month`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·领星汇率月度快照(my_rate=折算主口径;人工台账仅兜底/覆盖)';

-- source: sql/060_purchase_cash_cols.sql; type: ALTER TABLE
ALTER TABLE `fact_purchase_cash` MODIFY COLUMN `amount_total` DECIMAL(18,4) NOT NULL DEFAULT 0
  COMMENT '现金支出总额=total_price(货款+运费+其他);复核窗口内可刷新,过期冻结';

-- source: sql/061_lingxing_batch.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_lingxing_batch` (
  `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `wid`              INT NOT NULL COMMENT '仓库id',
  `wh_name`          VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '仓库名(WFS虚拟仓/美西ON仓等)',
  `batch_no`         VARCHAR(64)  NOT NULL COMMENT '批次号',
  `order_sn`         VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '来源单据号(入库/调拨等)',
  `type`             INT NOT NULL DEFAULT 0,
  `type_name`        VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '采购入库/调拨入库/其他入库…',
  `product_id`       VARCHAR(32)  NOT NULL DEFAULT '',
  `product_name`     VARCHAR(255) NOT NULL DEFAULT '',
  `sku`              VARCHAR(128) NOT NULL,
  `msku`             VARCHAR(128) NOT NULL DEFAULT '',
  `store_id`         VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '实测多为"0"，批次不绑店',
  `total`            INT NOT NULL DEFAULT 0 COMMENT '批次入库总量',
  `balance_num`      INT NOT NULL DEFAULT 0 COMMENT '结存数量',
  `transit_balance_num` INT NOT NULL DEFAULT 0 COMMENT '在途结存',
  `good_num`         INT NOT NULL DEFAULT 0,
  `bad_num`          INT NOT NULL DEFAULT 0,
  `purchase_price`   DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '采购单价(CNY)',
  `other_price`      DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '其他单价(接口字段名 price)',
  `head_stock_price` DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '头程单价',
  `stock_price`      DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '库存单价=采购+其他+头程(恒等已实证)',
  `stock_cost`       DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '结存成本=stock_price×balance_num',
  `amount`           DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '批次货款(purchase_price×total)',
  `head_stock_cost`  DECIMAL(18,4) NOT NULL DEFAULT 0,
  `fee`              DECIMAL(18,4) NOT NULL DEFAULT 0,
  `purchase_in_time` DATETIME NULL COMMENT '入库时间(期初切点判定用)',
  `batch_time`       DATETIME NULL,
  `inventory_age`    INT NOT NULL DEFAULT 0,
  `lx_update_time`   DATETIME NULL,
  `source_batch_json` JSON NULL COMMENT 'source_batch_no 数组(调拨链路)',
  `purchase_sns_json` JSON NULL COMMENT 'purchase_order_sns 数组',
  `supplier_names`   VARCHAR(255) NOT NULL DEFAULT '',
  `source_raw_id`    BIGINT UNSIGNED NULL,
  `created_at`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_lx_batch` (`wid`, `batch_no`(64)),
  KEY `idx_lx_batch_sku` (`sku`(64), `purchase_in_time`),
  KEY `idx_lx_batch_balance` (`balance_num`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·领星批次明细快照(期初一刀单价主源+当前存货价值)';

-- source: sql/062_finance_opening_cost.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_finance_opening_cost` (
  `id`                  BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `sku`                 VARCHAR(128) NOT NULL,
  `cutoff_date`         DATE NOT NULL DEFAULT '2026-05-01' COMMENT '一刀切点',
  `purchase_unit_cost`  DECIMAL(18,4) NOT NULL COMMENT '固定采购成本(CNY/件,财务定)',
  `firstmile_unit_cost` DECIMAL(18,4) NOT NULL COMMENT '固定头程成本(CNY/件,财务定)',
  `opening_unit_cost`   DECIMAL(18,4) NOT NULL COMMENT '期初一刀单价=采购+头程',
  `batch_unit_cost`     DECIMAL(18,4) NULL COMMENT '批次加权单价(参考,仅47个SKU有)',
  `snap_qty_0501`       INT NOT NULL DEFAULT 0 COMMENT '2026-05-01快照WFS可用数量(导入时点)',
  `precut_purchase_qty` INT NOT NULL DEFAULT 0 COMMENT '切点前采购总量(导入时点)',
  `value_source`        VARCHAR(24) NOT NULL COMMENT 'finance_fixed=批次无价财务定 / finance_override=财务覆盖批次价',
  `remark`              VARCHAR(500) NOT NULL DEFAULT '' COMMENT '人工备注列,永不覆盖',
  `created_by`          VARCHAR(64) NOT NULL DEFAULT '财务Excel回传20260813',
  `updated_by`          VARCHAR(64) NOT NULL DEFAULT '',
  `created_at`          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_opening_sku` (`sku`(64), `cutoff_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI财务·SKU期初一刀成本(人工层;财务定稿;同步永不覆盖)';

