-- source: sql/074_storage_weekly_charge.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_storage_weekly_charge (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform VARCHAR(32) NOT NULL DEFAULT 'walmart',
  store_id VARCHAR(64) NOT NULL,
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  amount DECIMAL(12,2) NOT NULL DEFAULT 0.00 COMMENT '该周仓储实扣额(正值,折扣后净额)',
  txn_rows INT NOT NULL DEFAULT 1 COMMENT '去重后参与求和的RAW行数',
  report_key VARCHAR(64) NOT NULL DEFAULT '' COMMENT '结算报告key(溯源,多行取首个)',
  report_date DATE NULL COMMENT '结算报告日期',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_swc (platform, store_id, period_start, period_end),
  KEY idx_swc_period (period_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='仓储费结算周实扣(statement RAW派生);唯一写入方expandStorageFeeDaily;评价=与fact_wfs_storage_fee账期两周合并守恒对照';

-- source: sql/082_order_item_and_fast_sales.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `raw_mp_order_item` (
  `id`                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform_order_no` VARCHAR(64)  NOT NULL COMMENT '平台单号',
  `order_item_no`     VARCHAR(64)  NOT NULL COMMENT '订单明细单号(商品行唯一)',
  `global_order_no`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '领星系统单号',
  `store_id`          VARCHAR(64)  NOT NULL COMMENT '经 storeIdNorm 修复精度后的店铺ID',
  `msku`              VARCHAR(128) NOT NULL,
  `purchase_time`     DATETIME     NULL COMMENT '订购时间(**美西**，走 usPacific)',
  `purchase_date`     DATE         NULL COMMENT '归因日=订购日(**美西日界**，与 saleStat 族同源)',
  `order_status`      INT          NOT NULL DEFAULT 0 COMMENT '领星订单状态,7=已取消/不发货(聚合时排除)',
  `quantity`          INT          NOT NULL DEFAULT 0,
  `item_price_amount` DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '商品金额(折前)。**这就是订单级成交金额，调价核对的判据**',
  `discount_amount`   DECIMAL(12,2) NOT NULL DEFAULT 0 COMMENT '折扣额,接口原符号(负值=优惠);0=全价单',
  `currency`          VARCHAR(8)   NOT NULL DEFAULT '',
  `row_json`          JSON         NOT NULL COMMENT '{order:单头精简, item:商品行原样}',
  `capture_batch`     VARCHAR(32)  NOT NULL DEFAULT '',
  `created_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_order_item` (`platform_order_no`, `order_item_no`),
  KEY `idx_oi_pdate` (`purchase_date`),
  KEY `idx_oi_store_msku` (`store_id`, `msku`(64)),
  KEY `idx_oi_store_date` (`store_id`, `purchase_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='RAW: 沃尔玛订单商品行全量(含全价单)。用途①调价核对的订单级成交价 ②T-1快速销量/销售额来源';

-- source: sql/082_order_item_and_fast_sales.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_sales_fast_daily` (
  `id`            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `platform`      VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`      VARCHAR(64)  NOT NULL,
  `item_id`       VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '经 dim_product(店铺+MSKU) 映射；未映射写空串，**不写NULL**（唯一键内 NULL 不去重，见2026-08-15 Schema审计）',
  `msku`          VARCHAR(128) NOT NULL,
  `stat_date`     DATE         NOT NULL COMMENT '业务日=订购日(美西日界)',
  `sales_qty`     INT          NOT NULL DEFAULT 0,
  `sales_amount`  DECIMAL(18,4) NOT NULL DEFAULT 0 COMMENT '折前商品金额合计(口径=item_price_amount之和)',
  `order_cnt`     INT          NOT NULL DEFAULT 0 COMMENT '**真实订单数**=COUNT(DISTINCT platform_order_no)。注意 fact_sales_daily.order_count 是 sales_qty 的拷贝(syncLingxingDailyToDb:452)，不是订单数，两者不可互相印证',
  `source_system` VARCHAR(32)  NOT NULL DEFAULT 'mp_order_api',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fast_sales` (`platform`, `store_id`, `msku`(64), `stat_date`),
  KEY `idx_fast_date` (`stat_date`),
  KEY `idx_fast_store_item` (`store_id`, `item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT: 订单接口现算的快速销量/销售额。仅用于权威链路(fact_sales_daily/fact_profit_daily)尚未覆盖的日期兜底；权威值到位后以权威为准，本表行保留作波动对照';

-- source: sql/083_ads_config_snapshot.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_campaign_snapshot_daily` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `snapshot_date`   DATE         NOT NULL COMMENT '快照日(**美西日界**,laToday(0));配置是当前值,故快照日=业务日',
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL,
  `advertiser_id`   VARCHAR(64)  NOT NULL DEFAULT '',
  `campaign_id`     VARCHAR(64)  NOT NULL,
  `campaign_name`   VARCHAR(512) NOT NULL DEFAULT '',
  `campaign_type`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT 'API原生值:sponsoredProducts-manual/-auto/sba/video',
  `campaign_status` VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '**实测枚举含 proposal**(SV 13行中7个),文档未列;做状态差分必须按实测枚举,不得照文档',
  `targeting_type`  VARCHAR(64)  NOT NULL DEFAULT '',
  `daily_budget`    DECIMAL(14,4) NULL COMMENT '实测全有值',
  `total_budget`    DECIMAL(14,4) NULL COMMENT '实测全空——与 budget_type 全为 daily 一致,属合理为空',
  `budget_type`     VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '实测全为 daily',
  `rollover`        VARCHAR(32)  NOT NULL DEFAULT '',
  `bidding_strategy` VARCHAR(32) NOT NULL DEFAULT '' COMMENT '实测 FIXED/DYNAMIC 有区分度(CN2502 191:9, CN2601 194:6)',
  `troas`           DECIMAL(14,4) NULL,
  `bidding_strategy_status` VARCHAR(32) NOT NULL DEFAULT '',
  `start_date`      DATE         NULL,
  `end_date`        DATE         NULL COMMENT '实测全空,与 budget_type=daily 一致',
  `entity_create_at` DATETIME    NULL,
  `row_json`        JSON         NOT NULL COMMENT '接口原始行原样留存',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_camp_snap` (`platform`, `store_id`, `campaign_id`, `snapshot_date`),
  KEY `idx_camp_snap_date` (`snapshot_date`),
  KEY `idx_camp_snap_store_date` (`store_id`, `snapshot_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT: 广告活动配置日快照(预算/竞价策略/状态)。差分输入层,前端不读。源=queryCampaignSpList';

-- source: sql/083_ads_config_snapshot.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_group_snapshot_daily` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `snapshot_date`   DATE         NOT NULL COMMENT '快照日(美西日界)',
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL,
  `advertiser_id`   VARCHAR(64)  NOT NULL DEFAULT '',
  `campaign_id`     VARCHAR(64)  NOT NULL DEFAULT '',
  `ad_group_id`     VARCHAR(64)  NOT NULL,
  `ad_group_name`   VARCHAR(512) NOT NULL DEFAULT '',
  `ad_group_status` VARCHAR(64)  NOT NULL DEFAULT '',
  `campaign_type`   VARCHAR(64)  NOT NULL DEFAULT '',
  `entity_create_at` DATETIME    NULL COMMENT '⚠️实测仅 20~39/200 有值 ⇒ **新增广告组不得靠本列判定,必须用 ad_group_id 首次出现日**',
  `row_json`        JSON         NOT NULL,
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_group_snap` (`platform`, `store_id`, `ad_group_id`, `snapshot_date`),
  KEY `idx_group_snap_date` (`snapshot_date`),
  KEY `idx_group_snap_camp` (`store_id`, `campaign_id`, `snapshot_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT: 广告组配置日快照。差分输入层,前端不读。源=queryGroupSpList(SP已实测1071/392组;SB/SV能否返回未证实,如实记录)';

-- source: sql/083_ads_config_snapshot.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_keyword_snapshot_daily` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `snapshot_date`   DATE         NOT NULL COMMENT '快照日(美西日界)',
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL,
  `advertiser_id`   VARCHAR(64)  NOT NULL DEFAULT '',
  `campaign_id`     VARCHAR(64)  NOT NULL DEFAULT '',
  `ad_group_id`     VARCHAR(64)  NOT NULL DEFAULT '',
  `keyword_id`      VARCHAR(64)  NOT NULL COMMENT '实测 200/200 有值。**空值一律写空串,不写NULL**(唯一键内NULL不去重,2026-08-15 Schema审计)',
  `keyword_name`    VARCHAR(512) NOT NULL DEFAULT '',
  `keyword_bid`     DECIMAL(14,4) NULL COMMENT '实测 200/200 有值。**这是当前出价,不随查询区间变**(两区间79个交集差异0)',
  `keyword_state`   VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '**开关状态**(enabled/paused,实测193:7)。「关闭关键词」判定用本列',
  `keyword_status`  VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '**审核状态**(实测 approved 全同值,无区分度)。⚠️不可用于开关判定,与上一列语义完全不同',
  `match_type`      VARCHAR(32)  NOT NULL DEFAULT '',
  `campaign_status` VARCHAR(64)  NOT NULL DEFAULT '',
  `ad_group_status` VARCHAR(64)  NOT NULL DEFAULT '',
  `campaign_type`   VARCHAR(64)  NOT NULL DEFAULT '',
  `row_json`        JSON         NOT NULL,
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_kw_snap` (`platform`, `store_id`, `keyword_id`, `snapshot_date`),
  KEY `idx_kw_snap_date` (`snapshot_date`),
  KEY `idx_kw_snap_group` (`store_id`, `ad_group_id`, `snapshot_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT: 关键词配置日快照(出价/开关状态)。差分输入层,前端不读。源=reportKeywordSpList/SvList/SbList。⚠️接口不返回item_id/msku,落商品维度须经fact_ads_product_daily的campaign→item映射';

-- source: sql/083_ads_config_snapshot.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_ads_snapshot_status` (
  `id`              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `snapshot_date`   DATE         NOT NULL COMMENT '快照日(美西日界)',
  `platform`        VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`        VARCHAR(64)  NOT NULL,
  `store_name`      VARCHAR(255) NOT NULL DEFAULT '',
  `entity_type`     VARCHAR(32)  NOT NULL COMMENT 'campaign / group / keyword',
  `campaign_type`   VARCHAR(64)  NOT NULL COMMENT 'sp(manual+auto) / sba / video',
  `api_path`        VARCHAR(255) NOT NULL DEFAULT '',
  `api_code`        VARCHAR(32)  NOT NULL DEFAULT '' COMMENT '接口业务码,0=成功',
  `api_total`       INT          NULL COMMENT '接口自报总数(data.total);为NULL表示接口未返回该字段',
  `fetched_rows`    INT          NOT NULL DEFAULT 0 COMMENT '实际取回行数',
  `pages_fetched`   INT          NOT NULL DEFAULT 0,
  `hit_page_cap`    TINYINT      NOT NULL DEFAULT 0 COMMENT '1=触顶分页上限,**必然不完整**',
  `is_complete`     TINYINT      NOT NULL DEFAULT 0 COMMENT '1=完整。判据:code=0 且 未触顶 且 (api_total为空 或 fetched_rows>=api_total)',
  `error_message`   TEXT         NULL COMMENT '失败时原样存接口 message,不加工',
  `created_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_snap_status` (`platform`, `store_id`, `entity_type`, `campaign_type`, `snapshot_date`),
  KEY `idx_snap_status_date` (`snapshot_date`, `is_complete`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT: 广告配置快照的完整性状态。差分脚本前置闸门——is_complete=0 的组合当天禁止产生关闭类事件。永久保留,不参与快照7天清理';

-- source: sql/084_event_ops_action_log.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `event_ops_action_log` (
  `id`             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `event_date`     DATE         NOT NULL COMMENT '事件业务日=后一个快照日(**美西日界**)',
  `platform`       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  `store_id`       VARCHAR(64)  NOT NULL,
  `store_name`     VARCHAR(255) NOT NULL DEFAULT '',
  `item_id`        VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '广告事件经 fact_ads_product_daily 映射;映射不到写空串,事件仍记。**不写NULL**',
  `msku`           VARCHAR(128) NOT NULL DEFAULT '' COMMENT '同上,**不写NULL**',

  `action_type`    VARCHAR(40)  NOT NULL COMMENT
    'price_change 售价调价 | ad_bid_change 关键词出价 | ad_budget_change 活动预算 | ad_strategy_change 竞价策略 | campaign_add/campaign_close 活动增关 | group_add/group_close 广告组增关 | keyword_add/keyword_close 关键词增关',
  `object_type`    VARCHAR(24)  NOT NULL DEFAULT '' COMMENT 'product / campaign / ad_group / keyword',
  `object_id`      VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '产品事件=msku;广告事件=campaign_id/ad_group_id/keyword_id',
  `object_name`    VARCHAR(512) NOT NULL DEFAULT '',
  `old_value`      VARCHAR(255) NOT NULL DEFAULT '',
  `new_value`      VARCHAR(255) NOT NULL DEFAULT '',

  
  
  
  
  `verify_status`  VARCHAR(24)  NOT NULL DEFAULT '' COMMENT 'consistent 一致 | inconsistent 不一致(标红) | no_order 无订单可核 | 空=该事件类型不适用',
  `verify_window`  VARCHAR(24)  NOT NULL DEFAULT '' COMMENT '实际用于核对的窗口:T0 / T0+T1 / 空',
  `matched_orders` INT          NOT NULL DEFAULT 0 COMMENT '成交单价与新价一致的订单行数',
  `checked_orders` INT          NOT NULL DEFAULT 0 COMMENT '参与核对的订单行数(排除 order_status=7)',

  `log_content`    TEXT         NOT NULL COMMENT '渲染好的中文句子,前端直接取用',
  `highlight`      TINYINT      NOT NULL DEFAULT 0 COMMENT '1=红色加粗(仅 verify_status=inconsistent 时置1)',
  `source`         VARCHAR(32)  NOT NULL DEFAULT 'snapshot_diff' COMMENT '本期唯一来源。领星操作日志接口已否决(API_MAP §2.8),故无 lingxing_log 来源',
  `operator`       VARCHAR(128) NOT NULL DEFAULT '' COMMENT '**恒为空**:沃尔玛侧拿不到操作人。谁做的由运营在人工日志里写',
  `detected_at`    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at`     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ops_action` (`platform`, `store_id`, `item_id`, `msku`(64), `event_date`, `action_type`, `object_id`),
  KEY `idx_ops_date` (`event_date`),
  KEY `idx_ops_store_item_date` (`store_id`, `item_id`, `event_date`),
  KEY `idx_ops_msku_date` (`store_id`, `msku`(64), `event_date`),
  KEY `idx_ops_verify` (`event_date`, `verify_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='EVENT: 系统运营日志(快照差分检出的人工运营动作)。与 biz_product_operation_log 人工日志并存;前端两列相邻。operator恒空——沃尔玛侧无操作人来源';

-- source: 交付件/DDL_AI人事_日志评级.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS ai_ops_log_review_item (
  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  week_start       DATE         NOT NULL COMMENT '评估周的周一（上周一）',
  owner_name       VARCHAR(128) NOT NULL,
  src_log_id       BIGINT UNSIGNED NOT NULL COMMENT '关联 biz_product_operation_log.id（只读引用）',
  log_date         DATE         NOT NULL,
  platform         VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  store_id         VARCHAR(64)  NOT NULL DEFAULT '',
  store_name       VARCHAR(128) NOT NULL DEFAULT '',
  item_id          VARCHAR(64)  NOT NULL DEFAULT '',
  msku             VARCHAR(128) NOT NULL DEFAULT '',
  log_excerpt      VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '日志内容快照（截断），防原行后续变更影响追溯',
  signals_excerpt  VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '当日运营提醒快照（截断）',
  verdict          VARCHAR(10)  NOT NULL COMMENT 'good / bad',
  reason           VARCHAR(500) NOT NULL DEFAULT '' COMMENT 'AI 判定理由',
  suggestion       VARCHAR(500) NOT NULL DEFAULT '' COMMENT 'AI 改进建议',
  llm_model        VARCHAR(64)  NOT NULL DEFAULT '',
  remark           VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注（异议登记），系统不覆盖',
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_review_item (week_start, src_log_id),
  KEY idx_ri_owner (week_start, owner_name),
  KEY idx_ri_verdict (week_start, verdict)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI运营日志评级-逐条明细（AI层，唯一写入方=aiOpsLogReview；remark人工可改）';

-- source: 交付件/DDL_AI人事_日志评级.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS ai_ops_log_review_summary (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  week_start        DATE         NOT NULL,
  owner_name        VARCHAR(128) NOT NULL,
  total_logs        INT          NOT NULL DEFAULT 0 COMMENT '窗口内该负责人日志行总数',
  substantive_logs  INT          NOT NULL DEFAULT 0 COMMENT '实质日志数（排除空/无运营话术）',
  reviewed_logs     INT          NOT NULL DEFAULT 0 COMMENT '实际送评条数（含截断说明）',
  good_count        INT          NOT NULL DEFAULT 0,
  bad_count         INT          NOT NULL DEFAULT 0,
  ai_comment        VARCHAR(2000) NOT NULL DEFAULT '' COMMENT 'AI 对该负责人的本周点评',
  status            VARCHAR(20)  NOT NULL DEFAULT 'success' COMMENT 'success / truncated / failed(LLM异常未出分)',
  llm_model         VARCHAR(64)  NOT NULL DEFAULT '',
  remark            VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统不覆盖',
  created_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_review_summary (week_start, owner_name(64)),
  KEY idx_rs_week (week_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='AI运营日志评级-每人每周汇总（AI层，唯一写入方=aiOpsLogReview）';

-- source: 交付件/DDL_CS测品预警台账.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_cs_test_alert` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '店铺ID',
  `item_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '沃尔玛ItemID',
  `msku` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MSKU（CS测品行维度）',
  `owner_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '负责人（花名册姓名快照）',
  `test_days_snapshot` int DEFAULT NULL COMMENT '触发时测品天数快照',
  `sales_qty_snapshot` int DEFAULT NULL COMMENT '触发时累计销量快照',
  `first_ad_date_snapshot` date DEFAULT NULL COMMENT '首次广告日期快照',
  `first_alert_date` date DEFAULT NULL COMMENT '首次预警日',
  `last_sent_date` date DEFAULT NULL COMMENT '最近发送日',
  `send_count` int NOT NULL DEFAULT '0' COMMENT '已发送次数（每工作日最多+1）',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '预警原因（人工填，≥15字；人工可改，系统不覆盖）',
  `reason_by` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '填写人',
  `reason_at` datetime DEFAULT NULL COMMENT '填写时间',
  `status` enum('open','resolved','closed_test_ended') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open' COMMENT 'open=待处理 resolved=已填原因 closed_test_ended=测品已结束',
  `penalty_count` int NOT NULL DEFAULT '0' COMMENT '累计扣分次数（每次5分，从第2次未填发送起累加）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cs_alert` (`platform`,`store_id`,`item_id`,`msku`(64)),
  KEY `idx_status` (`status`),
  KEY `idx_owner` (`owner_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='CS测品异常预警台账(reason人工不覆盖; 触发 test_days>20 且 累计销量>11 且 未结束)';

-- source: 交付件/DDL_WFS销量渠道事实表.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS fact_mp_sales_channel_daily (
  id                BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  stat_date         DATE NOT NULL COMMENT '订购日期（global_purchase_time，北京时间）',
  platform          VARCHAR(64) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  store_id          VARCHAR(64) NOT NULL COMMENT '店铺ID（订单顶层 store_id）',
  store_name        VARCHAR(255) DEFAULT NULL COMMENT '店铺名称（展示用）',
  item_id           VARCHAR(64) NOT NULL DEFAULT '' COMMENT '商品ID，经 dim_product(platform,store_id,msku) 反查；未命中为空串（订单接口 product_no 实测为空）',
  msku              VARCHAR(128) NOT NULL COMMENT 'MSKU（订单商品行 msku，聚合主键之一）',
  wfs_sales_qty     INT NOT NULL DEFAULT 0 COMMENT 'WFS销量：delivery_type=3 平台发货，排除 status=7 取消单',
  non_wfs_sales_qty INT NOT NULL DEFAULT 0 COMMENT '非WFS销量：delivery_type=2 自发货，排除取消单',
  mixed_sales_qty   INT NOT NULL DEFAULT 0 COMMENT '混合销量：delivery_type=1 中转值（2026-06 实测0单，列保留）',
  wfs_order_cnt     INT NOT NULL DEFAULT 0 COMMENT 'WFS订单数（非取消）',
  non_wfs_order_cnt INT NOT NULL DEFAULT 0 COMMENT '非WFS订单数（非取消）',
  source_system     VARCHAR(64) NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  source_raw_id     BIGINT DEFAULT NULL COMMENT 'RAW层ID（该日最后一页 raw_lingxing_api.id）',
  extra_json        JSON DEFAULT NULL COMMENT '扩展字段',
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uq_fact_mp_channel (stat_date, platform, store_id, msku(64)),
  KEY idx_fmc_item (item_id),
  KEY idx_fmc_store_date (store_id, stat_date),
  KEY idx_fmc_date (stat_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 每日按履约渠道分拆销量（领星订单接口聚合；唯一写入口=syncMpOrdersChannelDaily.ts）';

-- source: 交付件/DDL_产品GPT链接.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS dim_product_gpt_link (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform       VARCHAR(32)  NOT NULL DEFAULT 'walmart',
  item_id        VARCHAR(64)  NOT NULL,
  link_type      VARCHAR(16)  NOT NULL COMMENT 'keyword=关键词分析 / ads=广告分析',
  url            VARCHAR(1000) NOT NULL COMMENT 'GPT对话链接，必须 http(s):// 开头，非空（不允许清空只能替换）',
  effective_from DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '版本生效时刻=保存时刻；日志行按 created_at>=effective_from 匹配最新版本',
  updated_by     VARCHAR(64)  NOT NULL DEFAULT 'admin_ui',
  remark         VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统不覆盖',
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY idx_gpt_link_lookup (platform, item_id, link_type, effective_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='产品GPT分析链接版本表（append-only；唯一写入口=产品管理 update-gpt-link 接口）';

-- source: 交付件/DDL_清货已清渠道销量事实表.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `fact_channel_clearance_sales_daily` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date` date NOT NULL COMMENT '订购日期（global_purchase_time，北京时间）',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台：amazon / shein',
  `local_sku` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '领星本地SKU(=公司SKU)，订单 item_info.local_sku',
  `sales_qty` int NOT NULL DEFAULT '0' COMMENT '当日该平台该SKU销量（跨店铺汇总，排除 status=7 取消/is_delete=1）',
  `order_cnt` int NOT NULL DEFAULT '0' COMMENT '当日订单数（按订单去重）',
  `source_system` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id` bigint DEFAULT NULL COMMENT 'RAW层ID（该日最后一页 raw_lingxing_api.id）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fccs` (`stat_date`,`platform`,`local_sku`(64)),
  KEY `idx_fccs_platform_sku` (`platform`,`local_sku`(64)),
  KEY `idx_fccs_date` (`stat_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 亚马逊/希音每日按本地SKU销量(清货已清口径; 唯一写入口=syncMpOrdersChannelDaily.ts)';

-- source: 交付件/DDL_清货已清渠道销量事实表_v2按ASIN.sql; type: CREATE TABLE
CREATE TABLE `fact_channel_clearance_sales_daily` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `stat_date` date NOT NULL COMMENT '订购日期（global_purchase_time，北京时间）',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台：amazon / shein / temu / tiktok',
  `platform_ref` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台商品ID（亚马逊=ASIN/希音=SKC/TEMU/TikTok=平台商品ID），订单 item_info.product_no；聚合主键',
  `local_sku` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '本地SKU(=公司SKU) 参考快照，订单 item_info.local_sku',
  `sales_qty` int NOT NULL DEFAULT '0' COMMENT '当日该平台该商品ID销量（跨店铺汇总，排除 status=7 取消/is_delete=1）',
  `order_cnt` int NOT NULL DEFAULT '0' COMMENT '当日订单数（按订单去重）',
  `source_system` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'lingxing' COMMENT '来源系统',
  `source_raw_id` bigint DEFAULT NULL COMMENT 'RAW层ID（该日最后一页 raw_lingxing_api.id）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fccs` (`stat_date`,`platform`,`platform_ref`(64)),
  KEY `idx_fccs_platform_ref` (`platform`,`platform_ref`(64)),
  KEY `idx_fccs_date` (`stat_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='FACT层: 亚马逊/希音/TEMU/TikTok每日按平台商品ID销量(清货已清口径; 唯一写入口=syncMpOrdersChannelDaily.ts)';

-- source: 交付件/DDL_清货渠道目标列.sql; type: ALTER TABLE
ALTER TABLE biz_clearance_other_channel
  ADD COLUMN monthly_target INT NULL COMMENT '本月清货目标件数（人工，按 target_month 归属）' AFTER manual_stock,
  ADD COLUMN target_month VARCHAR(7) NULL COMMENT '目标归属月 2026-08' AFTER monthly_target,
  ADD COLUMN target_updated_by VARCHAR(64) NOT NULL DEFAULT '' AFTER target_month,
  ADD COLUMN target_updated_at DATETIME NULL AFTER target_updated_by,
  ADD COLUMN monthly_cleared INT NULL COMMENT '本月已清件数（人工维护，无平台数据源）' AFTER target_updated_at;

-- source: 交付件/DDL_绩效台账人工层_说明豁免.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `biz_perf_deduction_note` (
  `id`               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ref_deduction_id` BIGINT UNSIGNED NOT NULL COMMENT '=biz_perf_deduction.id，一对一',
  `ym`               CHAR(7)      NOT NULL COMMENT "扣分所属月 'YYYY-MM'（=deduction_date 归月，冗余便于窗口/月度过滤）",
  `explanation`      VARCHAR(500) NOT NULL DEFAULT '' COMMENT '绩效说明（被扣分本人填，解释/纠误判；人工列）',
  `explanation_by`   VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '说明填写人（花名册姓名快照）',
  `explanation_at`   DATETIME     NULL COMMENT '说明填写/最近修改时间',
  `exempt_status`    TINYINT      NOT NULL DEFAULT 0 COMMENT '0=正常计分 1=已豁免(该笔从合计免除，原扣分行保留)',
  `exempt_by`        VARCHAR(64)  NOT NULL DEFAULT '' COMMENT '豁免人（限黄少如/林翔）',
  `exempt_at`        DATETIME     NULL COMMENT '豁免时间',
  `exempt_reason`    VARCHAR(255) NOT NULL DEFAULT '' COMMENT '豁免理由（人工列）',
  `created_at`       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_note_ref` (`ref_deduction_id`),
  KEY `idx_note_ym` (`ym`),
  KEY `idx_note_exempt` (`exempt_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='绩效台账人工层：逐笔扣分的绩效说明+豁免（biz_perf_deduction 零改动；豁免=exempt_status=1 不删行）';

-- source: 交付件/DDL_绩效状态机_待认领扣分.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS event_owner_claim_alert (
  id                    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  platform              VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id              VARCHAR(64)  NOT NULL,
  store_name            VARCHAR(128) NOT NULL DEFAULT '' COMMENT '快照店铺名，展示用',
  item_id               VARCHAR(64)  NOT NULL,
  msku                  VARCHAR(128) NOT NULL,
  product_name          VARCHAR(255) NOT NULL DEFAULT '' COMMENT '快照产品名，展示用',
  cycle_start_date      DATE         NOT NULL COMMENT '本轮首次提醒日期=轮次锚点；清零重算=插入新行',
  first_notified_at     DATETIME     NULL COMMENT '首次提醒发送时间',
  second_notified_at    DATETIME     NULL COMMENT '二次提醒发送时间；非空即已触发扣分',
  deduction_points      INT          NOT NULL DEFAULT 0 COMMENT '本轮扣分，二提时写5；首提期认领保持0',
  claimed_by            VARCHAR(64)  NULL COMMENT '认领人=扣分承担人（dim_product.owner 变为在册人员时检测写入）',
  claimed_detected_at   DATETIME     NULL COMMENT '检测到认领的时间',
  announced_at          DATETIME     NULL COMMENT '认领+扣分随日报公布时间',
  supervisor_synced_at  DATETIME     NULL COMMENT '扣分同步黄少如时间',
  status                VARCHAR(20)  NOT NULL DEFAULT 'open'
    COMMENT 'open=跟踪中 claimed=已认领待公布 closed=已公布结案 void=作废(归档/停用退出清单)',
  remark                VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，系统任务不得覆盖',
  created_at            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_claim_cycle (platform, store_id, item_id, msku(64), cycle_start_date),
  KEY idx_oca_status (status),
  KEY idx_oca_claimed (claimed_by),
  KEY idx_oca_item (item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='待认领产品提醒轮次/认领/扣分状态机（EVENT层，唯一写入方=unmatchedOwnerNotify）';

-- source: 交付件/DDL_绩效状态机_待认领扣分.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_perf_deduction (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  deduction_date  DATE         NOT NULL COMMENT '扣分落账日期（=认领公布所在日报日）',
  owner_name      VARCHAR(64)  NOT NULL COMMENT '承担人（认领人），与花名册姓名一致',
  points          INT          NOT NULL COMMENT '扣分值，正数记录（如5）',
  biz_type        VARCHAR(40)  NOT NULL DEFAULT 'unclaimed_product' COMMENT '扣分类型，预留其他绩效场景',
  platform        VARCHAR(20)  NOT NULL DEFAULT 'walmart',
  store_id        VARCHAR(64)  NOT NULL DEFAULT '',
  item_id         VARCHAR(64)  NOT NULL DEFAULT '',
  msku            VARCHAR(128) NOT NULL DEFAULT '',
  ref_event_id    BIGINT UNSIGNED NULL COMMENT '关联 event_owner_claim_alert.id，防同轮重复落账',
  note            VARCHAR(255) NOT NULL DEFAULT '' COMMENT '人工备注，人工可改，系统不覆盖',
  created_by      VARCHAR(40)  NOT NULL DEFAULT 'system',
  created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_perf_ref (ref_event_id),
  KEY idx_perf_owner_date (owner_name, deduction_date),
  KEY idx_perf_type (biz_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='绩效扣分台账（append-only，AI智能人事系统数据底座；不UPDATE业务列、不DELETE）';

-- source: 交付件/SQL_建表_人工绩效凭证_20260731.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_perf_cert (
  ref_deduction_id BIGINT NOT NULL PRIMARY KEY COMMENT '挂 biz_perf_deduction.id',
  mime        VARCHAR(64)  NOT NULL DEFAULT 'image/jpeg',
  image_data  LONGBLOB     NOT NULL,
  uploaded_by VARCHAR(64)  NOT NULL DEFAULT '',
  uploaded_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人工绩效录入凭证图';

-- source: 交付件/walmart_sem_delivery/backend/048_sem_campaign_item_map.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS `dim_sem_campaign_item` (
  `id`            BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `platform`      VARCHAR(32) NOT NULL DEFAULT 'walmart' COMMENT '平台',
  `store_id`      VARCHAR(64) NOT NULL COMMENT '店铺ID',
  `campaign_id`   VARCHAR(64) NOT NULL COMMENT 'SEM Campaign ID（唯一稳定键）',
  `item_id`       VARCHAR(64) NOT NULL COMMENT '归属ItemID',
  `campaign_name` VARCHAR(255) DEFAULT NULL COMMENT '解析时的campaign名快照',
  `source`        VARCHAR(16) NOT NULL DEFAULT 'auto_name' COMMENT 'auto_name=名字解析 / manual=人工兜底（系统永不覆盖）',
  `remark`        VARCHAR(500) DEFAULT NULL COMMENT '人工备注（系统不覆盖）',
  `created_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at`    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sem_camp_item` (`platform`, `store_id`, `campaign_id`),
  KEY `idx_sem_camp_item` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='DIM层: SEM campaign→ItemID映射（Campaign ID稳定键；manual行人工兜底不覆盖）';

-- source: 月报系统/交付件/DDL_monthly.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS biz_monthly_plan (
  id                   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  plan_month           VARCHAR(7) NOT NULL COMMENT '规划月份 2026-08',
  platform             VARCHAR(20) NOT NULL DEFAULT 'walmart',
  store_id             VARCHAR(64) NOT NULL,
  item_id              VARCHAR(64) NOT NULL,
  msku                 VARCHAR(128) NOT NULL DEFAULT '',
  owner                VARCHAR(64) NOT NULL COMMENT '填报时的负责人',
  issue_text           TEXT NULL COMMENT '问题确认（预填月报问题，可补充）',
  indicator1_type      ENUM('清货','提高毛利率','提升销售额','新增变体','调整广告') NULL,
  indicator1_target    DECIMAL(14,2) NULL COMMENT '量化目标：件/%/$/个/%（随指标类型）',
  indicator2_type      ENUM('清货','提高毛利率','提升销售额','新增变体','调整广告') NULL,
  indicator2_target    DECIMAL(14,2) NULL,
  deadline             DATE NULL COMMENT '完成期限，默认当月末',
  normal_operation     TINYINT(1) NOT NULL DEFAULT 0 COMMENT '1=本月无优化计划正常运营（已表态）',
  note                 TEXT NULL COMMENT '补充说明（GPT建议可贴此处）',
  variant_actual       INT NULL COMMENT '新增变体人工汇报的实际数量（对账期填写）',
  variant_confirmed_by VARCHAR(64) NULL,
  variant_confirmed_at DATETIME NULL,
  created_by           VARCHAR(64) NOT NULL DEFAULT 'admin_ui',
  updated_by           VARCHAR(64) NOT NULL DEFAULT 'admin_ui',
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_plan (plan_month, platform, store_id, item_id, msku),
  KEY idx_month_owner (plan_month, owner)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='月度规划（人工数据；normal_operation=1时指标可空，否则指标1必填——由录入API约束）';

-- source: 月报系统/交付件/DDL_monthly.sql; type: CREATE TABLE
CREATE TABLE IF NOT EXISTS ai_monthly_issue_item (
  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  report_id        BIGINT UNSIGNED NOT NULL COMMENT 'ai_business_report.id',
  plan_month       VARCHAR(7) NOT NULL COMMENT '需填规划的月份（报告月的次月）',
  owner            VARCHAR(64) NOT NULL,
  platform         VARCHAR(20) NOT NULL DEFAULT 'walmart',
  store_id         VARCHAR(64) NOT NULL,
  item_id          VARCHAR(64) NOT NULL,
  msku             VARCHAR(128) NOT NULL DEFAULT '',
  issue_reasons    JSON NOT NULL COMMENT '命中的问题条件数组',
  suggested_action VARCHAR(255) NULL COMMENT '建议方向（复用规则信号suggested_action）',
  metrics_json     JSON NULL COMMENT '判定基线快照：毛利率/销量/广告占比/库存/周转等',
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_issue (report_id, platform, store_id, item_id, msku),
  KEY idx_month_owner (plan_month, owner)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='月报问题清单（AI层，生成器写入）';
